# ==============================================================================
# FUNÇÕES AUXILIARES — BANCO DE DADOS (DuckDB)
# ==============================================================================
# DuckDB only allows ONE connection per process to an on-disk database.
# We use a singleton connection + a threading lock so concurrent requests
# queue up rather than failing with BinderException.

_duckdb_conn = None
_duckdb_conn_lock = threading.Lock()

# Lazy one-time schema init (see _ensure_db_initialized). Deferred so the
# Werkzeug auto-reloader's supervisor process never opens the single-writer
# DuckDB file — only the worker that actually serves requests does.
_db_init_done = False
_db_init_lock = threading.RLock()     # re-entrant: init_db() re-enters via get_db_connection()
_db_init_tls  = threading.local()     # per-thread "currently initializing" flag


class _DuckDBHandle:
    """Proxy that holds _duckdb_conn_lock for its lifetime; close() releases it."""
    __slots__ = ('_conn', '_closed')

    def __init__(self, conn):
        self._conn = conn
        self._closed = False

    def __getattr__(self, name):
        return getattr(self._conn, name)

    def close(self):
        if not self._closed:
            self._closed = True
            _duckdb_conn_lock.release()


def _duckdb_connect_resilient(path, **kwargs):
    """``duckdb.connect`` that recovers from a corrupt/unreplayable WAL.

    A WAL left in a bad state (process killed mid-write, or the DuckDB quirk
    "Failure while replaying WAL … GetDefaultDatabase with no default database
    set") makes ``connect`` raise and blocks the DB entirely — which, on the
    Users DB, breaks even the lock/login flow. When that happens we quarantine
    the ``.wal`` (rename it aside) and retry once: the file reopens from its last
    checkpoint. Uncommitted WAL data is unrecoverable in this state anyway.

    Read-only opens can't quarantine (nothing should be writing), so they just
    propagate the original error.
    """
    try:
        return duckdb.connect(path, **kwargs)
    except Exception as e:
        msg = str(e).lower()
        wal_path = str(path) + ".wal"
        recoverable = ("wal" in msg or "replay" in msg) and os.path.exists(wal_path)
        if kwargs.get("read_only") or not recoverable:
            raise
        quarantine = wal_path + ".corrupt-" + time.strftime("%Y%m%d-%H%M%S")
        try:
            os.rename(wal_path, quarantine)
        except Exception:
            log.error("DuckDB WAL replay failed and quarantine failed:\n%s",
                      traceback.format_exc())
            raise e
        log.error("DuckDB WAL replay failed for %s (%s); quarantined WAL → %s and retried open",
                  path, e.__class__.__name__, os.path.basename(quarantine))
        return duckdb.connect(path, **kwargs)


def _duckdb_open():
    global _duckdb_conn
    abs_path = os.path.abspath(DB_PATH)
    _duckdb_conn = _duckdb_connect_resilient(
        abs_path,
        config={
            "autoinstall_known_extensions": "false",
            "autoload_known_extensions": "false",
        }
    )
    log.debug("DuckDB singleton opened → %s", abs_path)
    return _duckdb_conn


def get_db_connection(max_retries=6, retry_delay=0.05):
    global _duckdb_conn
    _ensure_db_initialized()        # lazy, one-time schema/migrations (no-op after first run)
    last_exc = None
    for attempt in range(max_retries):
        try:
            _duckdb_conn_lock.acquire()
            try:
                if _duckdb_conn is None:
                    _duckdb_open()
                else:
                    try:
                        _duckdb_conn.execute("SELECT 1")
                    except Exception:
                        log.warning("DuckDB singleton unhealthy, reconnecting…")
                        try:
                            _duckdb_conn.close()
                        except Exception:
                            pass
                        _duckdb_open()
            except Exception:
                _duckdb_conn_lock.release()
                raise
            return _DuckDBHandle(_duckdb_conn)
        except duckdb.IOException as e:
            # The inner handler above already released the lock before re-raising,
            # so we must NOT release it again here (that caused
            # "RuntimeError: release unlocked lock" masking the real IOException).
            last_exc = e
            if attempt < max_retries - 1:
                wait = retry_delay * (2 ** attempt)
                log.warning("DuckDB locked (attempt %d/%d), retrying in %.0fms…",
                            attempt + 1, max_retries, wait * 1000)
                time.sleep(wait)
        except Exception:
            log.error("Failed to open DuckDB:\n%s", traceback.format_exc())
            raise
    log.error("DuckDB unavailable after %d retries", max_retries)
    raise last_exc


def init_db():
    log.info("[init_db] Initializing database schema…")
    conn = get_db_connection()
    try:
        log.debug("[init_db] Creating sequence seq_vc_id")
        conn.execute("CREATE SEQUENCE IF NOT EXISTS seq_vc_id START 1")
        log.debug("[init_db] Creating table users")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS users (
                SID              VARCHAR PRIMARY KEY,
                Name             VARCHAR NOT NULL,
                Email            VARCHAR NOT NULL,
                Role_Description VARCHAR DEFAULT '',
                Position         VARCHAR DEFAULT '',
                Role             VARCHAR DEFAULT '',
                Status           VARCHAR DEFAULT 'Pending',
                IP_Address       VARCHAR,
                created_at       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        log.debug("[init_db] Creating table verification_codes")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS verification_codes (
                id         INTEGER  DEFAULT nextval('seq_vc_id') PRIMARY KEY,
                SID        VARCHAR  NOT NULL,
                code       VARCHAR(6) NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP NOT NULL,
                used       BOOLEAN  DEFAULT FALSE,
                attempts   INTEGER  DEFAULT 0
            )
        """)
        conn.execute("""
            CREATE INDEX IF NOT EXISTS idx_vc_lookup
            ON verification_codes (SID, used, expires_at)
        """)
        conn.execute("CREATE SEQUENCE IF NOT EXISTS seq_notif_id START 1")
        conn.execute("""
            CREATE TABLE IF NOT EXISTS notifications (
                id          INTEGER DEFAULT nextval('seq_notif_id') PRIMARY KEY,
                actor_sid   VARCHAR NOT NULL DEFAULT '',
                actor_name  VARCHAR NOT NULL DEFAULT '',
                action      VARCHAR NOT NULL DEFAULT '',
                page        VARCHAR NOT NULL DEFAULT '',
                detail      VARCHAR DEFAULT '',
                target_role VARCHAR DEFAULT '',
                target_sid  VARCHAR DEFAULT '',
                created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS push_subscriptions (
                endpoint   VARCHAR PRIMARY KEY,
                sid        VARCHAR NOT NULL DEFAULT '',
                role       VARCHAR DEFAULT '',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.commit()
        log.info("[init_db] Schema ready")
    except Exception:
        log.error("[init_db] FAILED:\n%s", traceback.format_exc())
        raise
    finally:
        conn.close()


def _migrate_schema():
    """Migra schemas antigos: sequence nula e colunas Role/Status ausentes."""
    log.info("[migrate] Checking schema migrations…")
    conn = get_db_connection()
    try:
        # Fix verification_codes: id NULL (schema sem sequence)
        try:
            row = conn.execute("SELECT COUNT(*) FROM verification_codes WHERE id IS NULL").fetchone()
            null_count = row[0] if row else 0
            log.debug("[migrate] verification_codes rows with NULL id: %d", null_count)
            if null_count > 0:
                log.warning("[migrate] Dropping verification_codes to fix NULL ids")
                conn.execute("DROP TABLE verification_codes")
                conn.execute("DROP SEQUENCE IF EXISTS seq_vc_id")
                conn.commit()
        except Exception:
            log.debug("[migrate] verification_codes check skipped: %s", traceback.format_exc())

        # Add verification_codes.attempts (per-code wrong-guess counter) if missing.
        try:
            vc_cols = [c[0] for c in conn.execute(
                "SELECT column_name FROM information_schema.columns WHERE table_name='verification_codes'"
            ).fetchall()]
            if vc_cols and 'attempts' not in vc_cols:
                log.warning("[migrate] Adding missing column verification_codes.attempts")
                conn.execute("ALTER TABLE verification_codes ADD COLUMN attempts INTEGER DEFAULT 0")
                conn.commit()
        except Exception:
            log.debug("[migrate] verification_codes.attempts check skipped: %s", traceback.format_exc())

        # Fix users: Role -> Role_Description + add Role + add Status
        try:
            cols = [c[0] for c in conn.execute(
                "SELECT column_name FROM information_schema.columns WHERE table_name='users'"
            ).fetchall()]
            log.debug("[migrate] users columns: %s", cols)

            if 'Role' in cols and 'Role_Description' not in cols:
                log.warning("[migrate] Renaming Role → Role_Description")
                conn.execute("ALTER TABLE users RENAME COLUMN Role TO Role_Description")
                conn.commit()
                cols = [c[0] for c in conn.execute(
                    "SELECT column_name FROM information_schema.columns WHERE table_name='users'"
                ).fetchall()]
                log.debug("[migrate] users columns after rename: %s", cols)

            if 'Role' not in cols:
                log.warning("[migrate] Adding missing column Role")
                conn.execute("ALTER TABLE users ADD COLUMN Role VARCHAR DEFAULT ''")
                conn.commit()

            if 'Status' not in cols:
                log.warning("[migrate] Adding missing column Status")
                conn.execute("ALTER TABLE users ADD COLUMN Status VARCHAR")
                conn.execute("UPDATE users SET Status = 'Pending' WHERE Status IS NULL")
                conn.commit()

            if 'Position' not in cols:
                log.warning("[migrate] Adding missing column Position")
                conn.execute("ALTER TABLE users ADD COLUMN Position VARCHAR DEFAULT ''")
                conn.commit()

            if 'Page_Access' not in cols:
                # JSON array of accessible page URLs. NULL/'' = not configured yet →
                # full access (backward compatible); a stored array = enforced allowlist.
                log.warning("[migrate] Adding missing column Page_Access")
                conn.execute("ALTER TABLE users ADD COLUMN Page_Access VARCHAR DEFAULT ''")
                conn.commit()

            log.info("[migrate] Schema migration complete")
        except Exception:
            log.error("[migrate] users schema migration FAILED:\n%s", traceback.format_exc())

        # Ensure notifications table exists
        try:
            conn.execute("SELECT 1 FROM notifications LIMIT 1")
        except Exception:
            log.warning("[migrate] notifications table missing — creating")
            try:
                conn.execute("CREATE SEQUENCE IF NOT EXISTS seq_notif_id START 1")
            except Exception:
                pass
            conn.execute("""
                CREATE TABLE IF NOT EXISTS notifications (
                    id          INTEGER DEFAULT nextval('seq_notif_id') PRIMARY KEY,
                    actor_sid   VARCHAR NOT NULL DEFAULT '',
                    actor_name  VARCHAR NOT NULL DEFAULT '',
                    action      VARCHAR NOT NULL DEFAULT '',
                    page        VARCHAR NOT NULL DEFAULT '',
                    detail      VARCHAR DEFAULT '',
                    target_role VARCHAR DEFAULT '',
                    target_sid  VARCHAR DEFAULT '',
                    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            conn.commit()
            log.info("[migrate] notifications table created")

        # notifications.target_sid — endereçamento a UM usuário, que target_role
        # não cobre: as atualizações de ticket vão só para o requester, e o papel
        # dele (BO/MO/FO/…) é compartilhado com o resto do time.
        try:
            ncols = [c[0] for c in conn.execute(
                "SELECT column_name FROM information_schema.columns WHERE table_name='notifications'"
            ).fetchall()]
            if ncols and 'target_sid' not in ncols:
                log.warning("[migrate] Adding missing column notifications.target_sid")
                conn.execute("ALTER TABLE notifications ADD COLUMN target_sid VARCHAR DEFAULT ''")
                conn.commit()
        except Exception:
            log.debug("[migrate] notifications.target_sid check skipped: %s", traceback.format_exc())

        # Ensure push_subscriptions table exists (Web Push)
        try:
            conn.execute("SELECT 1 FROM push_subscriptions LIMIT 1")
        except Exception:
            log.warning("[migrate] push_subscriptions table missing — creating")
            conn.execute("""
                CREATE TABLE IF NOT EXISTS push_subscriptions (
                    endpoint   VARCHAR PRIMARY KEY,
                    sid        VARCHAR NOT NULL DEFAULT '',
                    role       VARCHAR DEFAULT '',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            conn.commit()
            log.info("[migrate] push_subscriptions table created")
    finally:
        conn.close()


def _create_notification(actor_sid, actor_name, action, page, detail='', target_role='',
                         target_sid=''):
    """Publica uma notificação no sino. `target_role` restringe a um papel,
    `target_sid` a UM usuário (os dois vazios = todo mundo). Ver o filtro em
    `api_get_notifications`."""
    try:
        conn = get_db_connection()
        try:
            conn.execute(
                "INSERT INTO notifications (actor_sid, actor_name, action, page, detail, target_role, target_sid) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                [actor_sid or '', actor_name or '', action, page, detail or '',
                 target_role or '', (target_sid or '').strip().upper()]
            )
            conn.commit()
        finally:
            conn.close()
        # Wake subscribers' devices via Web Push (best-effort, off the request path).
        try:
            import threading
            threading.Thread(target=_push_notify,
                             args=(actor_sid or '', target_role or ''),
                             kwargs={'target_sid': (target_sid or '').strip().upper()},
                             daemon=True).start()
        except Exception:
            pass
    except Exception:
        log.error("[_create_notification] FAILED:\n%s", traceback.format_exc())


def _push_notify(actor_sid, target_role, target_sid=''):
    """Send a payloadless Web Push to every subscriber matching the
    notification's target_role (empty = everyone), except the actor. The
    Service Worker then fetches /api/notifications and shows it. Runs in a
    background thread; HTTP sends happen with no DB lock held.

    `target_sid` mirrors the feed filter: when set, only that user's devices
    are woken. Sem isso o celular do time inteiro apitaria por uma notificação
    que só o requester consegue abrir."""
    try:
        from apps.pages import webpush
        if not webpush.is_enabled():
            return
        conn = get_db_connection()
        try:
            if target_sid:
                # O actor é excluído nos outros ramos porque não precisa ser
                # avisado do que ele mesmo fez; aqui não: o destinatário é
                # explícito e pode até ser o próprio actor.
                rows = conn.execute(
                    "SELECT endpoint FROM push_subscriptions WHERE sid = ?",
                    [target_sid]).fetchall()
            elif target_role:
                rows = conn.execute(
                    "SELECT endpoint FROM push_subscriptions WHERE role = ? AND sid <> ?",
                    [target_role, actor_sid]).fetchall()
            else:
                rows = conn.execute(
                    "SELECT endpoint FROM push_subscriptions WHERE sid <> ?",
                    [actor_sid]).fetchall()
        finally:
            conn.close()
        dead = []
        for (endpoint,) in rows:
            code = webpush.send_push(endpoint)
            if code in (404, 410):   # subscription expired/unsubscribed
                dead.append(endpoint)
        if dead:
            conn = get_db_connection()
            try:
                for ep in dead:
                    conn.execute("DELETE FROM push_subscriptions WHERE endpoint = ?", [ep])
                conn.commit()
            finally:
                conn.close()
    except Exception:
        log.error("[_push_notify] FAILED:\n%s", traceback.format_exc())


def _nd_token(value):
    """Return a ' [ND:YYYY-MM-DD]' suffix for a notification detail so the bell can
    deep-link to that date (Accrual → ?date=, New Deals → ?tradedate=). Accepts a
    date, YYYYMMDD, YYYY-MM-DD or dd/mm/yyyy string; returns '' when unparseable.
    The topbar strips the token before displaying the detail."""
    if not value:
        return ''
    s = str(value).strip()
    d = None
    if re.match(r'^\d{8}$', s):
        try:
            d = datetime.strptime(s, '%Y%m%d')
        except Exception:
            d = None
    if d is None:
        try:
            d = _parse_date_any(s)
        except Exception:
            d = None
    return ' [ND:{}]'.format(d.strftime('%Y-%m-%d')) if d else ''


def get_user_by_sid(sid):
    log.debug("[get_user_by_sid] Looking up SID=%s", sid)
    conn = get_db_connection()
    try:
        result = conn.execute(
            "SELECT SID, Name, Email, Role_Description, Position, Role, Status, IP_Address FROM users WHERE SID = ?",
            [sid]
        ).fetchone()
        if result:
            user = {
                "SID": result[0],
                "Name": result[1],
                "Email": result[2],
                "Role_Description": result[3],
                "Position": result[4] or "",
                "Role": result[5],
                "Status": result[6] or "Pending",
                "IP_Address": result[7]
            }
            log.debug("[get_user_by_sid] Found: Name=%s Role=%s Status=%s IP=%s",
                      user["Name"], user["Role"], user["Status"], user["IP_Address"])
            return user
        log.debug("[get_user_by_sid] SID=%s not found in DB", sid)
        return None
    except Exception:
        log.error("[get_user_by_sid] Query error:\n%s", traceback.format_exc())
        raise
    finally:
        conn.close()


def get_all_users():
    conn = get_db_connection()
    try:
        rows = conn.execute("""
            SELECT SID, Name, Email, Role_Description, Position, Role, Status, IP_Address, created_at
            FROM users
            ORDER BY LOWER(COALESCE(Name, SID)) ASC
        """).fetchall()
        users = []
        for r in rows:
            users.append({
                "SID": r[0],
                "Name": r[1],
                "Email": r[2],
                "Role_Description": r[3] or "",
                "Position": r[4] or "",
                "Role": r[5] or "",
                "Status": r[6] or "Pending",
                "IP_Address": r[7],
                "created_at": r[8].strftime("%d %b, %Y") if r[8] else ""
            })
        return users
    finally:
        conn.close()


def get_role_groups():
    conn = get_db_connection()
    try:
        rows = conn.execute("""
            SELECT Role, COUNT(*) AS cnt,
                   LIST(SID   ORDER BY created_at DESC) AS sids,
                   LIST(Name  ORDER BY created_at DESC) AS names
            FROM users
            WHERE Role IS NOT NULL AND Role != ''
            GROUP BY Role
        """).fetchall()

        groups = {}
        for role, cnt, sids, names in rows:
            meta = ROLE_META.get(role, {
                'display': role, 'icon': 'ti-user',
                'description': '', 'responsibilities': [],
            })
            preview = [{'SID': s, 'Name': n}
                       for s, n in zip((sids or [])[:4], (names or [])[:4])]
            groups[role] = {
                'role': role,
                'display': meta['display'],
                'icon': meta['icon'],
                'description': meta['description'],
                'responsibilities': meta['responsibilities'],
                'count': cnt,
                'users': preview,
            }

        result = []
        for key in ['ADMIN', 'FO', 'MO', 'BO', 'INSTITUTIONAL', 'HUB']:
            if key in groups:
                result.append(groups[key])
        for key, val in groups.items():
            if key not in ['ADMIN', 'FO', 'MO', 'BO', 'INSTITUTIONAL', 'HUB']:
                result.append(val)
        return result
    finally:
        conn.close()


