def _get_logo_path():
    from flask import current_app
    candidates = [
        os.path.join(current_app.root_path, 'static', 'images', 'logo.png'),
        os.path.join(os.path.dirname(current_app.root_path), 'static', 'images', 'logo.png'),
        os.path.join(current_app.root_path, '..', 'static', 'images', 'logo.png'),
    ]
    for path in candidates:
        path = os.path.normpath(path)
        if os.path.exists(path):
            return path
    return None


def _get_email_asset(filename):
    """Resolve an image under static/images (same lookup as the logo) for inline
    e-mail embedding. Returns the path or None."""
    from flask import current_app
    candidates = [
        os.path.join(current_app.root_path, 'static', 'images', filename),
        os.path.join(os.path.dirname(current_app.root_path), 'static', 'images', filename),
        os.path.join(current_app.root_path, '..', 'static', 'images', filename),
    ]
    for path in candidates:
        path = os.path.normpath(path)
        if os.path.exists(path):
            return path
    return None


def _attach_email_gradient(container):
    """Attach the header gradient PNG as an inline cid:otc_gradient part — the
    shared e-mail header partial's Outlook/VML fallback (daily-metric pattern,
    now standard for every HTML e-mail). Works with or without an app context
    (threaded senders resolve the path relative to this module). Best-effort."""
    from email.mime.image import MIMEImage
    try:
        path = _get_email_asset('email-header-gradient.png')
    except Exception:                     # no app context (background thread)
        path = os.path.normpath(os.path.join(
            os.path.dirname(__file__), '..', 'static', 'images', 'email-header-gradient.png'))
        if not os.path.exists(path):
            path = None
    if not path:
        return
    try:
        with open(path, 'rb') as f:
            gimg = MIMEImage(f.read())
        gimg.add_header('Content-ID', '<otc_gradient>')
        gimg.add_header('Content-Disposition', 'inline', filename='email-header-gradient.png')
        container.attach(gimg)
    except Exception:
        log.warning('[email] could not attach header gradient:\n%s', traceback.format_exc())


@blueprint.app_context_processor
def _inject_email_grad_url():
    """Expose `grad_url` (the header gradient image) to every template, so the
    shared e-mail header partial renders the Outlook gradient without each route
    having to pass it.

    It is ALWAYS the inline `cid:` attachment, never an absolute http URL: every
    sender attaches the image via `_attach_email_gradient()`, and a remote URL is
    a download Outlook may block, delay or complete only in part — which is what
    printed a header half gradient / half flat #4f8ae2 (see the CETIP Files Saved
    e-mail of 03/08/2026). The cid: reference cannot fail halfway."""
    return {'grad_url': 'cid:otc_gradient'}


_STATIC_DIR = os.path.normpath(os.path.join(os.path.dirname(__file__), '..', 'static'))


def _asset_v(rel_path):
    """Token de cache de um estático: o mtime do arquivo.

    Substitui o `?v=20260728b` escrito à mão, que já falhou em produção: o §164
    mudou o `otc-fileupload.js` e ninguém trocou a string, então o navegador
    seguiu servindo o JS ANTERIOR — que lê o cadastro NOVO e trata o padrão
    `HO"MY"` como prefixo literal. Resultado na tela: Underlying Asset
    `HO"MY"U6` (§170). Com o mtime, publicar o arquivo já invalida o cache; não
    há string para alguém esquecer de bumpar.

    Falha (arquivo ausente) devolve '0': pior caso o cache não é invalidado,
    que é o comportamento de hoje — nunca uma página quebrada.
    """
    try:
        return str(int(os.path.getmtime(os.path.join(_STATIC_DIR, rel_path))))
    except Exception:
        return '0'


@blueprint.app_context_processor
def _inject_asset_v():
    return {'asset_v': _asset_v}


