    # Editing bank details requires re-approval → back to Pending (maker/checker).
    acc['bank'] = bank
    acc['agency'] = agency
    acc['account'] = account
    acc['status'] = 'Pending'
    acc['maker'] = sid
    acc['checker'] = ''
    _cpd_save_list(data)
    _notify_bank('Bank Account Edited', _bank_detail(spn, rec, _acc_disp(acc) + ' (Pending approval)'))
    return jsonify({'ok': True, 'account': acc})


