# ==============================================================================
# API — GENERIC NEW-DEALS CACHE (NDF FWD Start / NDF Other Publisher)
# Page + CRUD only. Same Deal+Client keyed JSON cache model as ndf-commodities.
# Import-parse / mapping-B3 / send-Conecta are product-specific and intentionally
# not wired here (handled per-product later).
# ==============================================================================

_GENERIC_ND_PRODUCTS = {
    'fwd-start': {
        'dir':    os.path.join(NEW_DEALS_CACHE_ROOT, 'NDF', 'FwdStart'),
        'suffix': '_ndffwdstart.json',
        'label':  'NDF FWD Start',
    },
    'other-publishers': {
        'dir':    os.path.join(NEW_DEALS_CACHE_ROOT, 'NDF', 'OtherPublisher'),
        'suffix': '_ndfotherpub.json',
        'label':  'NDF Other Publisher',
    },
    'vanilla': {
        'dir':    os.path.join(NEW_DEALS_CACHE_ROOT, 'NDF', 'Vanilla'),
        'suffix': '_ndfvanilla.json',
        'label':  'NDF Vanilla',
    },
}


def _generic_nd_cfg(product):
    return _GENERIC_ND_PRODUCTS.get(product)


# Product Type shown on the Pending Confirmation row — the three generic NDF
# pages (Vanilla / Other Publisher / FWD Start) all report plain 'NDF'.
_GENERIC_ND_PC_TYPE = {'fwd-start': 'NDF',
                       'other-publishers': 'NDF',
                       'vanilla': 'NDF'}


def _generic_nd_pending_status(product, deal):
    """Pending Status for a mapped (Status→Success) generic-NDF deal.
    Rules: (Settlement − Trade) ≤ 60 corridos → 'Exception FepWeb' (all three);
    FWD Start → 'Pending OTC'; Other Publisher/Vanilla → by the counterparty's
    SIGNATURE TYPE in RefData: Internal → Exception Digital Fep Web,
    Digital → Pending Digital Signature, Manual (and unregistered) → Pending
    Original."""
    td = _parse_date_any(deal.get('TradeDate', ''))
    md = _parse_date_any(deal.get('SettlementDate', ''))
    if td and md and (md - td).days <= 60:
        return 'Exception FepWeb'
    if product == 'fwd-start':
        return 'Pending OTC'
    rec = _fxo_refdata_by_spn().get(_norm_spn(deal.get('SPN', '')), {})
    sig = _pc_norm(rec.get('SIGNATURE TYPE', ''))
    if sig == 'internal':
        return _PC_PASTDUE_STATUS          # Exception Digital Fep Web
    if sig == 'digital':
        return 'Pending Digital Signature'
    return 'Pending Original'


def _generic_nd_pc_trigger(product, deal):
    """→ Pending Confirmation on Status Success (same trigger as the other New
    Deals products; _pc_save_from_deal skips internal/intragroup legs itself).
    FWD Start rows are keyed by the mapped B3 ID, not the Deal name."""
    tn = None
    if product == 'fwd-start':
        tn = str(deal.get('B3_ID', '') or '').strip() or None
    _pc_save_from_deal(deal, _GENERIC_ND_PC_TYPE.get(product, 'NDF'),
                       pending_status=_generic_nd_pending_status(product, deal),
                       trade_number=tn)


# ==============================================================================
# NEW DEALS — CONFIRMATIONS (NDF Commodities · Termo de Mercadoria)
# Portado da macro legada (TERMO.doc): as confirmações são segregadas por
# contraparte × mercadoria × família de moeda do strike, POR trade date, sempre
# excluindo as pontas internas (Client = Banco J.P. Morgan ou Lawton — as
# pernas banco×lawton/lawton×banco não geram confirmação de cliente). Por
# enquanto só o template "strike em USD" existe na web (os demais — BRL,
# PLATTS, Palm Oil — chegam depois); grupos das outras famílias aparecem na
# listagem como "template pendente".
# ==============================================================================

_CONF_INTERNAL_RE = re.compile(r'J\.?P\.?\s*MORGAN|LAWTON', re.IGNORECASE)
# A confirmação só pode ser gerada quando as operações estão com status
# Success (registro concluído); Canceled nunca conta para nada.
_CONF_GEN_ELIGIBLE_STATUS = 'Success'
_CONF_MONTHS_PT = ('Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
                   'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro')
# Código de mês dos contratos futuros (Jan..Dez) — usado no texto do CO1-2.
_CONF_FUT_MONTH_CODE = {1: 'F', 2: 'G', 3: 'H', 4: 'J', 5: 'K', 6: 'M',
                        7: 'N', 8: 'Q', 9: 'U', 10: 'V', 11: 'X', 12: 'Z'}
# Normalizações de tickers legados (herdadas da macro).
_CONF_TICKER_MAP = {'NACX0005': 'VLSFO (AMFSA00)', 'PEURNPHY': 'PAAL00',
                    'PCRUDTB1': 'PCAAS00'}

_conf_subj_cache = {'mtime': None, 'map': {}}


def _conf_subjacente_map():
    """Subjacente.json indexado pelo código do ativo → bolsa/fator/mercadoria.
    Cache por mtime (o arquivo muda pouco e tem ~8k registros)."""
    fp = os.path.normpath(os.path.join(os.path.dirname(__file__), '..',
                                       'static', 'data', 'Subjacente.json'))
    try:
        mt = os.path.getmtime(fp)
    except OSError:
        return {}
    if _conf_subj_cache['mtime'] == mt:
        return _conf_subj_cache['map']
    out = {}
    try:
        with open(fp, encoding='utf-8') as fh:
            for rec in json.load(fh):
                if not isinstance(rec, dict):
                    continue
                code = str(rec.get('Codigo do Ativo Subjacente') or '').strip()
                if not code:
                    continue
                out.setdefault(code, {
                    'bolsa':      str(rec.get('Bolsa de Negociacao') or '').strip(),
                    'fator':      rec.get('Fator Conversao'),
                    'mercadoria': str(rec.get('Commodity') or '').strip(),
                })
    except Exception:
        log.error('[conf] Subjacente.json load failed:\n%s', traceback.format_exc())
        return {}
    _conf_subj_cache['mtime'] = mt
    _conf_subj_cache['map'] = out
    return out


def _conf_fmt_date(v):
    d = _parse_date_any(v)
    return d.strftime('%d/%m/%Y') if d else str(v or '').strip()


def _conf_date_extenso(v):
    d = _parse_date_any(v)
    if not d:
        return str(v or '').strip()
    return '{:02d} de {} de {}'.format(d.day, _CONF_MONTHS_PT[d.month - 1], d.year)


def _conf_fmt_cnpj(v):
    digits = re.sub(r'\D', '', str(v or ''))
    if len(digits) > 14 and digits.endswith('0'):   # sobra de '.0' de planilha
        digits = digits[:14]
    if len(digits) != 14:
        return str(v or '').strip()
    return '{}.{}.{}/{}-{}'.format(digits[:2], digits[2:5], digits[5:8],
                                   digits[8:12], digits[12:])


def _conf_to_float(v):
    s = str(v if v is not None else '').strip().replace(' ', '')
    if not s:
        return None
    # "1.234,56" (BR) vs "1,234.56" (US) vs "1234.56"
    if ',' in s and '.' in s:
        s = s.replace('.', '').replace(',', '.') if s.rfind(',') > s.rfind('.') \
            else s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return None


def _conf_fmt_num(v, dec=4):
    """Formato pt-BR: milhar '.', decimal ','. dec=None mantém 0–4 casas."""
    n = _conf_to_float(v)
    if n is None:
        return str(v or '').strip()
    if dec is None:
        dec = 0 if float(n).is_integer() else 4
    s = '{:,.{d}f}'.format(n, d=dec)
    return s.replace(',', '\x00').replace('.', ',').replace('\x00', '.')


def _conf_prev_biz(dt, n):
    """dt recuado n dias úteis ANBIMA (espelho de _anbima_add_biz)."""
    hols, cur, left = _anbima_holidays(), dt, n
    while left > 0:
        cur -= timedelta(days=1)
        if cur.weekday() < 5 and cur.strftime('%Y-%m-%d') not in hols:
            left -= 1
    return cur


def _conf_load_ndfcomm(ref):
    """Deals do day-file de NDF Commodities da reference date (lista de dicts)."""
    fname = ref.strftime('%Y%m%d') + '_ndfcomm.json'
    fp = os.path.join(NDF_COMM_CACHE_DIR, ref.strftime('%Y'), ref.strftime('%m'), fname)
    if not os.path.isfile(fp):
        return []
    try:
        with open(fp, encoding='utf-8') as fh:
            data = json.load(fh)
        return [d for d in data if isinstance(d, dict)] if isinstance(data, list) else []
    except Exception:
        log.warning('[conf] cannot read %s', fp)
        return []


def _conf_deal_family(deal, subj):
    """Família de template de um deal: strike-usd | brl | brl-platts | platts | palm-oil."""
    ccy = str(deal.get('StrikeCurrency') or '').strip().upper()
    is_brl = ccy in ('BRR', 'BRL')
    merc = str(deal.get('Commodities') or (subj or {}).get('mercadoria') or '').strip().upper()
    bolsa = str((subj or {}).get('bolsa') or '').upper()
    is_platts = 'BLOOMB' in bolsa          # na macro: exchange "BLOOMBGERG" = Platts
    if merc == 'OLEO DE PALMA EM USD':
        return 'palm-oil'
    if is_brl and is_platts:
        return 'brl-platts'
    if is_brl:
        return 'brl'
    if is_platts:
        return 'platts'
    return 'strike-usd'


# ── Estado das confirmações (ciclo próprio: New → Generated → Success) ───────
# Persistido por reference date em day-files próprios; a chave é o grupo
# (acronym | mercadoria | família). Generated = Word+PDF salvos no Inventory;
# Success = validado na janela de checklist com o preview do PDF.
CONF_STATE_DIR = os.path.normpath(os.path.join(
    os.path.dirname(__file__), "..", "static", "data", "cache", "confirmations", "ndf-comm"
))


def _conf_state_path(ref, product='ndf-comm'):
    base = os.path.join(os.path.dirname(CONF_STATE_DIR), product)
    return os.path.join(base, ref.strftime('%Y'), ref.strftime('%m'),
                        ref.strftime('%Y%m%d') + '_conf.json')


def _conf_key(acr, merc, fam):
    return '{}|{}|{}'.format(acr, merc, fam)


def _conf_state_load(ref, product='ndf-comm'):
    fp = _conf_state_path(ref, product)
    if not os.path.isfile(fp):
        return {}
    try:
        with open(fp, encoding='utf-8') as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _conf_state_save(ref, state, product='ndf-comm'):
    """Os 4 callers já envolvem _conf_state_load + este save num `with
    _cache_lock` — é lá que o ciclo tem de ser atômico. O lock aqui é
    reentrante e serve de rede: gravação de estado nunca sai destravada."""
    with _cache_lock:
        fp = _conf_state_path(ref, product)
        os.makedirs(os.path.dirname(fp), exist_ok=True)
        _atomic_write_json(fp, state)


def _conf_segregate(deals, family_fn):
    """Segregação das confirmações da data: um grupo por contraparte ×
    mercadoria × família de template (pontas internas fora, Canceled fora).
    Retorna (groups, status_counter, total_considerado)."""
    subj_map = _conf_subjacente_map()
    groups, statuses, total = {}, Counter(), 0
    for deal in deals:
        st = str(deal.get('Status') or 'New').strip() or 'New'
        if st == 'Canceled':
            continue
        client = str(deal.get('Client') or '').strip()
        if _CONF_INTERNAL_RE.search(client):
            continue                        # pontas banco/lawton não confirmam
        ua = str(deal.get('UnderlyingAsset') or '').strip()
        subj = subj_map.get(ua)
        merc = str(deal.get('Commodities') or (subj or {}).get('mercadoria') or ua or '').strip().upper()
        fam = family_fn(deal, subj)
        acr = str(deal.get('Acronym') or '').strip() or client or '(sem contraparte)'
        key = (acr, merc, fam)
        g = groups.setdefault(key, {
            'acronym': acr, 'client': client, 'mercadoria': merc, 'family': fam,
            'count': 0, 'eligible': 0,
        })
        g['count'] += 1
        if not g['client'] and client:
            g['client'] = client
        if st == _CONF_GEN_ELIGIBLE_STATUS:
            g['eligible'] += 1
        statuses[st] += 1
        total += 1
    ordered = sorted(groups.values(),
                     key=lambda g: (g['acronym'], g['mercadoria'], g['family']))
    return ordered, statuses, total


def _conf_ndfcomm_groups(ref):
    return _conf_segregate(_conf_load_ndfcomm(ref), _conf_deal_family)


@blueprint.route('/api/new-deals/ndf-commodities/confirmations')
def api_ndfcomm_confirmations():
    """Grupos de confirmação da reference date, com o link de geração quando o
    template da família já existe (por ora, só strike-usd)."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    ds = (request.args.get('date') or '').strip()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()
    groups, _statuses, _total = _conf_ndfcomm_groups(ref)
    state = _conf_state_load(ref)
    out = []
    for g in groups:
        available = g['family'] in _CONF_FAMILY_TEMPLATES
        entry = state.get(_conf_key(g['acronym'], g['mercadoria'], g['family'])) or {}
        status = entry.get('status') or 'New'
        qs = ('date=' + ref.strftime('%Y-%m-%d')
              + '&acronym=' + quote(g['acronym'])
              + '&mercadoria=' + quote(g['mercadoria']))
        url = _CONF_FAMILY_TEMPLATES[g['family']][1] + '?' + qs if available else None
        validate_url = ('/confirmation/ndf-comm/validate?' + qs + '&family=' + quote(g['family'])) \
            if status in ('Generated', 'Success') else None
        out.append({
            'acronym': g['acronym'], 'client': g['client'],
            'mercadoria': g['mercadoria'], 'family': g['family'],
            'count': g['count'], 'eligible': g['eligible'],
            'available': available, 'url': url,
            'status': status, 'validate_url': validate_url,
        })
    return jsonify({'success': True, 'date': ref.strftime('%Y-%m-%d'), 'groups': out})


def _conf_co12_text(deal, index):
    """Texto dinâmico do ticker CO1-2 (Brent rolling), portado da macro:
    mercados CO<letra><dígito do ano> dos dois meses seguintes ao settlement."""
    settle = _parse_date_any(deal.get('SettlementDate'))
    refd = _parse_date_any(deal.get('FixingEndDate'))
    if not settle or not refd:
        return 'CO1-2'
    two_before = _conf_prev_biz(refd, 2)
    one_before = _conf_prev_biz(refd, 1)

    def _mkt(offset):
        m = settle.month + offset
        y = settle.year + (m - 1) // 12
        m = (m - 1) % 12 + 1
        letter = _CONF_FUT_MONTH_CODE.get(m, '?')
        return 'CO{}{}'.format(letter, str(y)[-1])

    return ('Para as Datas de Verificação entre a Data Inicial de Verificação de Mercadoria e '
            '{} significa {} e para as Datas de Verificação em {} e {}, significa {}'
            .format(two_before.strftime('%d/%m/%Y'), _mkt(1),
                    one_before.strftime('%d/%m/%Y'), refd.strftime('%d/%m/%Y'), _mkt(2)))


def _conf_cgd_lookup(first):
    """Data do CGD da contraparte (CounterpartyDetails, primeiro item Active),
    por extenso quando o valor cadastrado é uma data."""
    cgd_txt = ''
    try:
        rec = _cpd_find(_cpd_load(), str(first.get('SPN') or '').strip())
        for item in _cgd_norm((rec or {}).get('CGD')):
            if (item.get('status') or 'Active') == 'Active' and item.get('value'):
                cgd_txt = item['value']
                break
    except Exception:
        log.warning('[conf] CGD lookup failed:\n%s', traceback.format_exc())
    if cgd_txt and _parse_date_any(cgd_txt):
        cgd_txt = _conf_date_extenso(cgd_txt)
    return cgd_txt


# Palm Oil: no TERMO - PALM OIL.doc a bolsa e a taxa de conversão são texto
# fixo do documento (a macro escrevia as duas constantes, não o cadastro do
# Subjacente) — o Anexo II define a "MYR USD" nominalmente e o Anexo I cita a
# Bursa. Não é de-para: não há chave, é o texto legal desta família.
_CONF_PALMOIL_BOLSA = 'MDE-BURSA MALAYSIA'
_CONF_PALMOIL_TAXA_CONV = 'MYR USD'

# Famílias com template web disponível: template Jinja + rota de geração.
# (brl-platts entra quando o respectivo .doc for enviado.)
_CONF_FAMILY_TEMPLATES = {
    'strike-usd': ('confirmations/ndf-comm-strike-usd.html',        '/confirmation/ndf-comm/strike-usd'),
    'platts':     ('confirmations/ndf-comm-platts-strike-usd.html', '/confirmation/ndf-comm/platts-strike-usd'),
    'brl':        ('confirmations/ndf-comm-strike-brl.html',        '/confirmation/ndf-comm/strike-brl'),
    'palm-oil':   ('confirmations/ndf-comm-palmoil-strike-myrusd.html',
                   '/confirmation/ndf-comm/palmoil-strike-myrusd'),
}


def _conf_sort_key_venc(item):
    """Ordena a Tabela de Referência pela Data de Vencimento, do vencimento mais
    próximo ao mais distante. Deal sem data parseável vai para o fim em vez de
    virar 'ano 1' e encabeçar a tabela; o sort do Python é estável, então
    vencimentos iguais mantêm a ordem em que o deal entrou no cache."""
    d = _parse_date_any((item[0] or {}).get('SettlementDate'))
    return (1, datetime.max.date()) if d is None else (0, d)


def _conf_pick_eligible(deals, acr, merc, family, family_fn):
    """Deals elegíveis (status Success, pontas internas fora) de um grupo
    contraparte × mercadoria × família → [(deal, subj)], **ordenados por Data de
    Vencimento**: é assim que as linhas saem no Anexo I das confirmações e é
    também a ordem em que o XML soma as operações."""
    subj_map = _conf_subjacente_map()
    picked = []
    for deal in deals:
        st = str(deal.get('Status') or 'New').strip() or 'New'
        if st != _CONF_GEN_ELIGIBLE_STATUS:
            continue
        client = str(deal.get('Client') or '').strip()
        if _CONF_INTERNAL_RE.search(client):
            continue
        ua = str(deal.get('UnderlyingAsset') or '').strip()
        subj = subj_map.get(ua)
        d_merc = str(deal.get('Commodities') or (subj or {}).get('mercadoria') or ua or '').strip().upper()
        d_acr = str(deal.get('Acronym') or '').strip() or client or '(sem contraparte)'
        if d_acr != acr or d_merc != merc:
            continue
        if family_fn(deal, subj) != family:
            continue
        picked.append((deal, subj))
    picked.sort(key=_conf_sort_key_venc)
    return picked


def _conf_pick_ndfcomm(ref, acr, merc, family):
    return _conf_pick_eligible(_conf_load_ndfcomm(ref), acr, merc, family,
                               _conf_deal_family)


def _conf_generation_page(family):
    """Renderiza a confirmação pré-preenchida (família dada) para um grupo
    contraparte × mercadoria da reference date. O template mantém o painel de
    edição — o usuário revisa/ajusta, imprime e salva no Inventory."""
    if not session.get('authenticated'):
        return redirect(url_for('pages_blueprint.sign_in_page'))
    ds = (request.args.get('date') or '').strip()
    acr = (request.args.get('acronym') or '').strip()
    merc = (request.args.get('mercadoria') or '').strip().upper()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()

    picked = _conf_pick_ndfcomm(ref, acr, merc, family)

    if not picked:
        return ('Nenhuma operação elegível para essa confirmação '
                '(contraparte {} × {} em {}).'.format(acr, merc, ref.strftime('%d/%m/%Y')), 404)

    first = picked[0][0]
    rows, warnings = [], []
    for i, (deal, subj) in enumerate(picked, start=1):
        ua = str(deal.get('UnderlyingAsset') or '').strip()
        ticker = _CONF_TICKER_MAP.get(ua, ua)
        if ua == 'CO1-2':
            ticker = _conf_co12_text(deal, i)
        fator = _conf_to_float((subj or {}).get('fator'))
        strike = _conf_to_float(deal.get('Strike'))
        forward = _conf_fmt_num(strike * (fator if fator else 1.0)) if strike is not None \
            else str(deal.get('Strike') or '').strip()
        f_ini = _parse_date_any(deal.get('FixingStartDate'))
        f_fim = _parse_date_any(deal.get('FixingEndDate'))
        bullet = bool(f_ini and f_fim and f_ini == f_fim)
        direction = str(deal.get('Direction') or '').strip().upper()
        row = {
            'num':       str(deal.get('Deal') or '').strip(),
            'comprador': 'Parte B' if direction.startswith('S') else 'Parte A',
            'ticker':    ticker,
            # No Platts a coluna é "Fonte de Divulgação" e o valor é PLATTS;
            # no Palm Oil a bolsa é fixa (a macro escrevia a constante, não o
            # cadastro do Subjacente — o documento cita a Bursa nominalmente).
            'bolsa':     'PLATTS' if family == 'platts'
                         else _CONF_PALMOIL_BOLSA if family == 'palm-oil'
                         else str((subj or {}).get('bolsa') or '').strip(),
            'qtd':       _conf_fmt_num(str(deal.get('TotalNotional') or '').replace('-', ''), dec=None),
            'premio':    'Não Aplicável',
            'devedor':   'Não Aplicável',
            'dtPremio':  'Não Aplicável',
            'forward':   forward,
            'dtIni':     'Não Aplicável' if bullet else _conf_fmt_date(deal.get('FixingStartDate')),
            'dtFim':     _conf_fmt_date(deal.get('FixingEndDate')),
            'dtVenc':    _conf_fmt_date(deal.get('SettlementDate')),
        }
        if family == 'palm-oil':
            # Três colunas a mais no Anexo I. A Data de Verificação da Taxa de
            # Conversão é a Data Final de Verificação da Mercadoria (na macro,
            # os dois campos saem do mesmo values[17]) — inclusive no bullet,
            # onde só a data INICIAL vira 'Não Aplicável'.
            row['bbg'] = 'Não Aplicável'
            row['taxaConv'] = _CONF_PALMOIL_TAXA_CONV
            row['dtTaxaConv'] = _conf_fmt_date(deal.get('FixingEndDate'))
        if family == 'brl':
            # BRL: janela de verificação da USD PTAX = janela de fixing (macro
            # legada usava as mesmas datas); bullet zera a inicial também.
            row['ptaxIni'] = 'Não Aplicável' if bullet else _conf_fmt_date(deal.get('FixingStartDate'))
            row['ptaxFim'] = _conf_fmt_date(deal.get('FixingEndDate'))
        else:
            row['ptax'] = _conf_fmt_date(deal.get('FXConvDate'))
        rows.append(row)
        if subj is None:
            warnings.append('Ativo {} sem cadastro no Subjacente (bolsa/fator ausentes).'.format(ua))

    # CGD da contraparte (CounterpartyDetails, primeiro item Active).
    cgd_txt = _conf_cgd_lookup(first)
    if not cgd_txt:
        warnings.append('CGD não cadastrado no Reference Data — preencha no painel.')

    trade_date = first.get('TradeDate') or ref
    conf = {
        'ref_date':     ref.strftime('%Y-%m-%d'),
        'cgd_date':     cgd_txt,
        'parteb_nome':  str(first.get('Client') or '').strip(),
        'parteb_cnpj':  _conf_fmt_cnpj(first.get('TaxID')),
        'data_neg':     _conf_fmt_date(trade_date),
        'data_extenso': _conf_date_extenso(trade_date),
        'mercadoria':   merc,
        'acronym':      acr,
        'rows':         rows,
        'warnings':     warnings,
    }
    return render_template(_CONF_FAMILY_TEMPLATES[family][0], conf=conf)


@blueprint.route('/confirmation/ndf-comm/strike-usd')
def confirmation_ndfcomm_strike_usd():
    return _conf_generation_page('strike-usd')


@blueprint.route('/confirmation/ndf-comm/platts-strike-usd')
def confirmation_ndfcomm_platts_strike_usd():
    return _conf_generation_page('platts')


@blueprint.route('/confirmation/ndf-comm/strike-brl')
def confirmation_ndfcomm_strike_brl():
    return _conf_generation_page('brl')


@blueprint.route('/confirmation/ndf-comm/palmoil-strike-myrusd')
def confirmation_ndfcomm_palmoil_strike_myrusd():
    return _conf_generation_page('palm-oil')


# ── XML do contrato (FepWeb) por confirmação ─────────────────────────────────
# Cada confirmação gerada produz um XML de mesmo nome-base do documento na mesma
# pasta.
#
# A moeda do XML NÃO é o ISO-4217 numérico: é o "código de cadastro" do BACEN,
# que a tabela Currency Base (/mapping) já registra por moeda — USD é 220 e não
# 840, BRL é 790 e não 986. Havia um dicionário ISO fixo aqui, e era ele que
# punha 840 no arquivo. Fora estar errado, era um de-para no código: o mapping
# é a fonte, e uma moeda nova passa a valer sem release.
_CONF_CNPJ_BANCO = '33172537000198'


def _conf_ccy_num(ccy):
    """Código de cadastro (3 dígitos) da moeda pelo mapping Currency Base.

    Aceita o SIMBOLO (USD) e o ATHENA CODE (USB, BRR) — o cache de deals traz
    ora um, ora outro. Vazio quando a moeda não está cadastrada; quem chama
    avisa, em vez de inventar um código."""
    s = str(ccy or '').strip().upper()
    if not s:
        return ''
    code = _moeda_num_code(s)
    if code:
        return code
    ath, _weak, _inv = _mapping_ccy_maps()          # Athena → ISO
    return _moeda_num_code(ath.get(s, '')) if ath.get(s) else ''


def _conf_ccy_is_brl(ccy):
    """True para a moeda nacional em qualquer das grafias que aparecem nos
    caches (BRL, BRR e o próprio código de cadastro 790)."""
    s = str(ccy or '').strip().upper()
    if s in ('BRL', 'BRR', '790'):
        return True
    ath, _weak, _inv = _mapping_ccy_maps()
    return ath.get(s, '') == 'BRL'


def _conf_strike_adj(deal, subj):
    """Strike ajustado pelo quoted-in-cents (Fator Conversão do Subjacente
    quando cadastrado; senão /100 quando o deal está marcado YES)."""
    strike = _conf_to_float(deal.get('Strike'))
    if strike is None:
        return None
    fator = _conf_to_float((subj or {}).get('fator'))
    if fator:
        return strike * fator
    if str(deal.get('QuotedInCents') or '').strip().upper() == 'YES':
        return strike / 100.0
    return strike


def _conf_ndf_xml(picked, merc, ref, tipo='NDF', prefixo='NDF_Comm',
                  ccy_field='StrikeCurrency', warn_no_spot=True):
    """(numero_contrato, xml_string, warnings) do grupo de deals da confirmação.

    valor            = Σ notional × strike ajustado × Spot FXRate
    valorEstrangeiro = Σ notional × strike ajustado
    numeroContrato   = DealName quando a confirmação tem 1 operação
                       (Mondelez: DealName_Mercadoria); com várias,
                       <prefixo>_YYYYMMDD_Mercadoria.
    Opções de Commodities usam o mesmo contrato com tipo='Option' e
    prefixo='Opt_Comm' — o resto do padrão é idêntico ao NDF.
    Opções de Câmbio (FXO) usam prefixo='Opt_FXO' e leem a moeda do
    ccy_field='UnderlyingAsset'; nelas o strike já é a cotação em BRL, então
    não há Spot FXRate para buscar e warn_no_spot=False cala o aviso que só
    faria sentido em commodities."""
    warnings = []
    first = picked[0][0]
    trade_dt = _parse_date_any(first.get('TradeDate')) or ref
    merc_tag = re.sub(r'\s+', '_', str(merc or '').strip().upper())

    if len(picked) > 1:
        numero = '{}_{}_{}'.format(prefixo, trade_dt.strftime('%Y%m%d'), merc_tag)
    else:
        numero = str(first.get('Deal') or '').strip() or \
            '{}_{}_{}'.format(prefixo, trade_dt.strftime('%Y%m%d'), merc_tag)
        if 'MONDELEZ' in str(first.get('Client') or '').upper():
            numero = numero + '_' + merc_tag

    ccy = str(first.get(ccy_field) or '').strip().upper()
    # Strike em Reais não tem perna estrangeira: moedaEstrangeira e
    # valorEstrangeiro saem VAZIOS (preenchê-los com 790/valor em BRL declararia
    # uma operação em moeda estrangeira que não existe).
    is_brl = _conf_ccy_is_brl(ccy)
    ccy_num = '' if is_brl else _conf_ccy_num(ccy)
    if not is_brl and not ccy_num:
        warnings.append('Moeda do strike "{}" sem código de cadastro na tabela Currency Base '
                        '(/mapping) — moedaEstrangeira ficou vazia no XML.'.format(ccy))

    valor = 0.0
    valor_estr = 0.0
    venc = None
    for deal, subj in picked:
        qty = _conf_to_float(str(deal.get('TotalNotional') or '').replace('-', ''))
        strike_adj = _conf_strike_adj(deal, subj)
        if qty is None or strike_adj is None:
            warnings.append('Operação {}: notional/strike não numérico — fora dos valores do XML.'
                            .format(deal.get('Deal')))
            continue
        leg = qty * strike_adj
        valor_estr += leg
        spot = _conf_to_float(deal.get('SpotFXRate'))
        if spot is None:
            spot = 1.0
            if warn_no_spot and ccy not in ('BRL', 'BRR'):
                warnings.append('Operação {}: sem Spot FXRate — valor em BRL ficou igual ao estrangeiro.'
                                .format(deal.get('Deal')))
        valor += leg * spot
        sd = _parse_date_any(deal.get('SettlementDate'))
        if sd and (venc is None or sd > venc):
            venc = sd

    cnpj_cli = re.sub(r'\D', '', str(first.get('TaxID') or ''))
    if len(cnpj_cli) != 14:
        warnings.append('CNPJ da contraparte fora do padrão (14 dígitos): "{}".'
                        .format(first.get('TaxID')))

    return numero, _conf_xml_doc(numero, tipo, valor, ccy_num,
                                 '' if is_brl else valor_estr, cnpj_cli,
                                 trade_dt, venc), warnings


def _conf_xml_doc(numero, tipo, valor, ccy_num, valor_estr, cnpj_cli, trade_dt, venc):
    """XML do contrato. `valor_estr` vazio (strike em BRL) sai como tag vazia,
    igual aos campos que o FepWeb já recebe em branco."""
    return (
        '<contrato>\n'
        '  <numeroContrato>{numero}</numeroContrato>\n'
        '  <tipoOperacao>{tipo}</tipoOperacao>\n'
        '  <tipoEvento>N</tipoEvento>\n'
        '  <valor>{valor:.2f}</valor>\n'
        '  <moedaEstrangeira>{ccy}</moedaEstrangeira>\n'
        '  <valorEstrangeiro>{valor_estr}</valorEstrangeiro>\n'
        '  <codigoNatureza></codigoNatureza>\n'
        '  <descricaoNatureza></descricaoNatureza>\n'
        '  <pagadorRecebidorExterior></pagadorRecebidorExterior>\n'
        '  <cnpjBanco>{cnpj_banco}</cnpjBanco>\n'
        '  <cnpjCliente>{cnpj_cli}</cnpjCliente>\n'
        '  <cnpjCorretora></cnpjCorretora>\n'
        '  <dataOperacao>{dt_op}</dataOperacao>\n'
        '  <dataVencimento>{dt_venc}</dataVencimento>\n'
        '</contrato>\n'
    ).format(numero=numero, tipo=tipo, valor=valor, ccy=ccy_num,
             valor_estr=('{:.2f}'.format(valor_estr) if valor_estr != '' else ''),
             cnpj_banco=_CONF_CNPJ_BANCO, cnpj_cli=cnpj_cli,
             dt_op=trade_dt.strftime('%Y%m%d'),
             dt_venc=venc.strftime('%Y%m%d') if venc else '')


def _conf_pc_set_fepweb(trade_numbers, numero):
    """Grava o numeroContrato na coluna FepWeb ID das linhas do Pending
    Confirmation cujo Trade Number é uma das operações da confirmação
    (linhas de NDF Comm são chaveadas pelo Deal name). Varre os 3 DBs."""
    tns = [str(t or '').strip() for t in trade_numbers if str(t or '').strip()]
    if not tns:
        return 0
    updated = 0
    placeholders = ', '.join('?' for _ in tns)
    for fname in _PC_DBS.values():
        path = os.path.join(_PC_DB_DIR, fname)
        if not os.path.isfile(path):
            continue
        try:
            con = duckdb.connect(path)
            try:
                before = con.execute(
                    'SELECT count(*) FROM {} WHERE trim("Trade Number") IN ({})'
                    .format(_PC_TABLE, placeholders), tns).fetchone()[0]
                if before:
                    con.execute(
                        'UPDATE {} SET "FepWeb ID" = ? WHERE trim("Trade Number") IN ({})'
                        .format(_PC_TABLE, placeholders), [numero] + tns)
                    updated += before
            finally:
                con.close()
        except Exception:
            log.warning('[conf] FepWeb ID update failed em %s:\n%s', fname,
                        traceback.format_exc())
    return updated


@blueprint.route('/api/confirmation/ndf-comm/save', methods=['POST'])
def api_conf_ndfcomm_save():
    """Salva a confirmação (com os ajustes feitos no painel) em Word + PDF no
    Electronic Inventory: Confirmations/YYYY/mm. Mês/dd/<produto>/<arquivo>.
    O .doc é o próprio HTML do documento (o Word abre HTML nativamente — os
    templates legados .doc já eram HTML do Word); o PDF é gerado via reportlab."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    payload = request.get_json(silent=True) or {}
    family = (payload.get('family') or 'strike-usd').strip()
    if family not in _CONF_FAMILY_TEMPLATES:
        return jsonify({'success': False, 'message': 'Template not available for this family yet.'}), 400
    fields = payload.get('fields') or {}
    rows = [r for r in (payload.get('rows') or []) if isinstance(r, dict)]
    if not rows:
        return jsonify({'success': False, 'message': 'No operations to save.'}), 400
    # CGD é cláusula do documento ("ambos firmados entre as Partes em <data>"):
    # sem ela a confirmação sai com a lacuna em branco e vai assim para a
    # contraparte. Trava no servidor, não só no painel — o POST é público para
    # qualquer sessão autenticada.
    if not str(fields.get('cgd_date') or '').strip():
        return jsonify({'success': False, 'error': 'missing_cgd',
                        'message': 'Data do CGD não cadastrada para esta contraparte. '
                                   'Cadastre o CGD no Reference Data (ou preencha o campo '
                                   'Data do CGD no painel) antes de salvar a confirmação.'}), 400

    acr = str(payload.get('acronym') or '').strip() or 'CONFIRMATION'
    merc = str(payload.get('mercadoria') or '').strip()
    conf = {
        'ref_date':     str(payload.get('date') or '').strip(),
        'cgd_date':     str(fields.get('cgd_date') or '').strip(),
        'parteb_nome':  str(fields.get('parteb_nome') or '').strip(),
        'parteb_cnpj':  str(fields.get('parteb_cnpj') or '').strip(),
        'data_neg':     str(fields.get('data_neg') or '').strip(),
        'data_extenso': str(fields.get('data_extenso') or '').strip(),
        'acronym':      acr,
        'mercadoria':   merc,
        'rows':         rows,
        'warnings':     [],
    }

    try:
        from apps.pages.confirmation_pdfs import termo_pdf
        pdf_bytes = termo_pdf(conf, variant={'strike-usd': 'usd', 'platts': 'platts',
                                             'brl': 'brl', 'palm-oil': 'palmoil'}[family])
    except ImportError:
        return jsonify({'success': False,
                        'message': 'reportlab is not installed — run pip install -r requirements.txt.'}), 500
    except Exception:
        log.error('[conf] PDF build failed:\n%s', traceback.format_exc())
        return jsonify({'success': False, 'message': 'PDF generation failed.'}), 500

    doc_html = render_template(_CONF_FAMILY_TEMPLATES[family][0],
                               conf=conf, doc_only=True)

    ref = _parse_date_any(payload.get('date')) or _parse_date_any(conf['data_neg']) or datetime.now()
    # Pasta da contraparte no Electronic Inventory — mesma árvore que o upload
    # manual da página (<Cliente>\Confirmations\YYYY\mm. Month\dd\<produto>),
    # para a confirmação aparecer no browse do EI junto dos demais documentos.
    client_dir = _ei_resolve_client_dir(conf['parteb_nome'] or acr, create=True)
    dir_path = os.path.join(client_dir, 'Confirmations',
                            ref.strftime('%Y'), _ei_month_folder(ref.strftime('%m')),
                            ref.strftime('%d'), 'NDF Commodities')
    # Nome no padrão legado, mantendo o prefixo contraparte × mercadoria.
    if len(rows) == 1 and str(rows[0].get('num') or '').strip():
        base = '{} - {} - CONFIRMAÇÃO DE OPERAÇÕES DE DERIVATIVOS nº {}'.format(
            acr, merc, str(rows[0]['num']).strip())
    else:
        base = '{} - {} - CONFIRMAÇÃO DE OPERAÇÕES DE DERIVATIVOS - {}'.format(
            acr, merc, ref.strftime('%Y%m%d'))
    base = _ei_sanitize(base)

    try:
        os.makedirs(_ei_long_path(dir_path), exist_ok=True)
        candidate, n = base, 0
        while os.path.exists(_ei_long_path(os.path.join(dir_path, candidate + '.doc'))) or \
                os.path.exists(_ei_long_path(os.path.join(dir_path, candidate + '.pdf'))):
            n += 1
            candidate = '{} ({})'.format(base, n)
        doc_path = os.path.join(dir_path, candidate + '.doc')
        pdf_path = os.path.join(dir_path, candidate + '.pdf')
        with open(_ei_long_path(doc_path), 'w', encoding='utf-8') as fh:
            fh.write(doc_html)
        with open(_ei_long_path(pdf_path), 'wb') as fh:
            fh.write(pdf_bytes)

        # XML do contrato (FepWeb): mesmo nome do numeroContrato, mesma pasta.
        # Calculado a partir dos deals-fonte (status Success) do grupo — não das
        # linhas editadas no painel — porque valor/moeda/CNPJ vêm do cache.
        xml_files, numero_contrato, xml_warns, fep_updated = [], '', [], 0
        picked = _conf_pick_ndfcomm(ref, acr, merc, family)
        if picked:
            numero_contrato, xml_str, xml_warns = _conf_ndf_xml(picked, merc, ref)
            # Mesmo nome-base do .doc/.pdf: os três arquivos da confirmação
            # ficam juntos na listagem da pasta. O numeroContrato continua
            # dentro do XML (é ele que o FepWeb lê), só não nomeia mais o
            # arquivo — com vários deals ele era genérico
            # (NDF_Comm_YYYYMMDD_MERC) e não dizia de qual confirmação era.
            xbase = candidate
            xcand, xn = xbase, 0
            while os.path.exists(_ei_long_path(os.path.join(dir_path, xcand + '.xml'))):
                xn += 1
                xcand = '{} ({})'.format(xbase, xn)
            xml_path = os.path.join(dir_path, xcand + '.xml')
            with open(_ei_long_path(xml_path), 'w', encoding='utf-8') as fh:
                fh.write(xml_str)
            xml_files.append(xml_path)
            # numeroContrato → coluna FepWeb ID das operações no Pending Confirmation
            fep_updated = _conf_pc_set_fepweb([d.get('Deal') for d, _s in picked],
                                              numero_contrato)
        else:
            xml_warns = ['XML não gerado: nenhuma operação com status Success no grupo.']
    except Exception as exc:
        log.error('[conf] save failed:\n%s', traceback.format_exc())
        return jsonify({'success': False, 'message': 'Could not write to the Inventory share: ' + str(exc)}), 500

    # Ciclo da confirmação: salvar = Generated (a validação com checklist +
    # preview do PDF é o passo seguinte, que leva a Success).
    ref_state = _parse_date_any(payload.get('date')) or ref
    with _cache_lock:
        state = _conf_state_load(ref_state)
        state[_conf_key(acr, merc, family)] = {
            'status': 'Generated', 'doc': doc_path, 'pdf': pdf_path,
            'saved_by': session.get('user_sid', ''),
            'saved_at': datetime.now().strftime('%d/%m/%Y %H:%M:%S'),
            'checks': {}, 'validated_by': '', 'validated_at': '',
        }
        _conf_state_save(ref_state, state)

    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Confirmation Saved', 'NDF Comm',
                         '{} · {} ({} op{})'.format(acr, merc, len(rows),
                                                    '' if len(rows) == 1 else 's'))
    validate_url = ('/confirmation/ndf-comm/validate?date=' + ref_state.strftime('%Y-%m-%d')
                    + '&acronym=' + quote(acr) + '&mercadoria=' + quote(merc)
                    + '&family=' + quote(family))
    return jsonify({'success': True, 'files': [doc_path, pdf_path] + xml_files,
                    'numero_contrato': numero_contrato,
                    'fepweb_updated': fep_updated,
                    'warnings': xml_warns,
                    'validate_url': validate_url})


def _conf_state_entry_or_404(args, product='ndf-comm'):
    """(ref, key, entry, err_response) para os endpoints de validação/preview."""
    ds = (args.get('date') or '').strip()
    acr = (args.get('acronym') or '').strip()
    merc = (args.get('mercadoria') or '').strip().upper()
    fam = (args.get('family') or 'strike-usd').strip()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()
    key = _conf_key(acr, merc, fam)
    entry = _conf_state_load(ref, product).get(key)
    if not entry:
        return ref, key, None, ('Confirmação ainda não gerada para {} × {} em {}.'
                                .format(acr, merc, ref.strftime('%d/%m/%Y')), 404)
    return ref, key, entry, None


@blueprint.route('/api/confirmation/ndf-comm/pdf')
def api_conf_ndfcomm_pdf():
    """Preview inline do PDF salvo da confirmação (para a janela de validação)."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    _ref, _key, entry, err = _conf_state_entry_or_404(request.args)
    if err:
        return err
    pdf_path = (entry or {}).get('pdf') or ''
    if not pdf_path or not os.path.isfile(pdf_path):
        return ('PDF não encontrado no Inventory ({}).'.format(pdf_path), 404)
    return send_file(pdf_path, mimetype='application/pdf', as_attachment=False,
                     download_name=os.path.basename(pdf_path))


@blueprint.route('/confirmation/ndf-comm/validate')
def confirmation_ndfcomm_validate():
    """Janela de validação da confirmação gerada: checklist + preview do PDF.
    Todos os checks marcados → Validate → status Success."""
    if not session.get('authenticated'):
        return redirect(url_for('pages_blueprint.sign_in_page'))
    ref, _key, entry, err = _conf_state_entry_or_404(request.args)
    if err:
        return err
    acr = (request.args.get('acronym') or '').strip()
    merc = (request.args.get('mercadoria') or '').strip().upper()
    fam = (request.args.get('family') or 'strike-usd').strip()
    qs = ('date=' + ref.strftime('%Y-%m-%d') + '&acronym=' + quote(acr)
          + '&mercadoria=' + quote(merc) + '&family=' + quote(fam))
    return render_template('confirmations/validate.html',
                           acronym=acr, mercadoria=merc, family=fam,
                           ref_date=ref.strftime('%Y-%m-%d'),
                           ref_date_disp=ref.strftime('%d/%m/%Y'),
                           status=entry.get('status') or 'Generated',
                           saved_by=entry.get('saved_by') or '',
                           saved_at=entry.get('saved_at') or '',
                           validated_by=entry.get('validated_by') or '',
                           validated_at=entry.get('validated_at') or '',
                           checks=entry.get('checks') or {},
                           api_base='/api/confirmation/ndf-comm',
                           pdf_url='/api/confirmation/ndf-comm/pdf?' + qs)


@blueprint.route('/api/confirmation/ndf-comm/validate', methods=['POST'])
def api_conf_ndfcomm_validate():
    """Marca a confirmação como Success após o checklist completo."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    payload = request.get_json(silent=True) or {}
    ref, key, entry, err = _conf_state_entry_or_404(payload)
    if err:
        return jsonify({'success': False, 'message': err[0]}), err[1]
    checks = payload.get('checks') or {}
    if not checks or not all(bool(v) for v in checks.values()):
        return jsonify({'success': False,
                        'message': 'Todos os itens do checklist precisam ser confirmados.'}), 400
    with _cache_lock:
        state = _conf_state_load(ref)
        entry = state.get(key) or entry
        entry['status'] = 'Success'
        entry['checks'] = {str(k): True for k in checks}
        entry['validated_by'] = session.get('user_sid', '')
        entry['validated_at'] = datetime.now().strftime('%d/%m/%Y %H:%M:%S')
        state[key] = entry
        _conf_state_save(ref, state)
    acr, merc = (key.split('|') + ['', ''])[:2]
    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Confirmation Validated', 'NDF Comm', '{} · {}'.format(acr, merc))
    return jsonify({'success': True, 'status': 'Success'})


# ==============================================================================
# NEW DEALS — CONFIRMATIONS (Commodities Options · Opção de Commodities)
# Mesmo fluxo do NDF Commodities (segregação contraparte × mercadoria ×
# família, ciclo New → Generated → Success, Word+PDF+XML no Inventory), portado
# da macro legada de opções (criar_documento/process_documents). Diferenças:
# a coluna Nº do Anexo I usa o Deal name (opção não tem mais mnemônico), o
# ticker CO1-2 tem template legado próprio (família 'co1-2', pendente) e o XML
# sai com tipoOperacao Option e prefixo Opt_Comm no numeroContrato — o resto
# do padrão do contrato é idêntico ao do NDF.
# ==============================================================================

_CONF_OPT_FAMILY_TEMPLATES = {
    'strike-usd': ('confirmations/opt-comm-strike-usd.html', '/confirmation/opt-comm/strike-usd'),
}


def _conf_load_optcomm(ref):
    """Deals do day-file de Option/Commodities da reference date."""
    fname = ref.strftime('%Y%m%d') + '_optcomm.json'
    fp = os.path.join(CACHE_BASE_DIR, ref.strftime('%Y'), ref.strftime('%m'), fname)
    if not os.path.isfile(fp):
        return []
    try:
        with open(fp, encoding='utf-8') as fh:
            data = json.load(fh)
        return [d for d in data if isinstance(d, dict)] if isinstance(data, list) else []
    except Exception:
        log.warning('[conf] cannot read %s', fp)
        return []


def _conf_opt_family(deal, subj):
    """Família de template de uma opção: as mesmas do NDF + 'co1-2' (a macro
    legada tinha um OPÇÃO COMMODITY-CO1-2.doc próprio para o Brent rolling)."""
    if str(deal.get('UnderlyingAsset') or '').strip() == 'CO1-2':
        return 'co1-2'
    return _conf_deal_family(deal, subj)


def _conf_optcomm_groups(ref):
    return _conf_segregate(_conf_load_optcomm(ref), _conf_opt_family)


def _conf_pick_optcomm(ref, acr, merc, family):
    return _conf_pick_eligible(_conf_load_optcomm(ref), acr, merc, family,
                               _conf_opt_family)


@blueprint.route('/api/new-deals/opt-commodities/confirmations')
def api_optcomm_confirmations():
    """Grupos de confirmação de Opção de Commodities da reference date."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    ds = (request.args.get('date') or '').strip()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()
    groups, _statuses, _total = _conf_optcomm_groups(ref)
    state = _conf_state_load(ref, 'opt-comm')
    out = []
    for g in groups:
        available = g['family'] in _CONF_OPT_FAMILY_TEMPLATES
        entry = state.get(_conf_key(g['acronym'], g['mercadoria'], g['family'])) or {}
        status = entry.get('status') or 'New'
        qs = ('date=' + ref.strftime('%Y-%m-%d')
              + '&acronym=' + quote(g['acronym'])
              + '&mercadoria=' + quote(g['mercadoria']))
        url = _CONF_OPT_FAMILY_TEMPLATES[g['family']][1] + '?' + qs if available else None
        validate_url = ('/confirmation/opt-comm/validate?' + qs + '&family=' + quote(g['family'])) \
            if status in ('Generated', 'Success') else None
        out.append({
            'acronym': g['acronym'], 'client': g['client'],
            'mercadoria': g['mercadoria'], 'family': g['family'],
            'count': g['count'], 'eligible': g['eligible'],
            'available': available, 'url': url,
            'status': status, 'validate_url': validate_url,
        })
    return jsonify({'success': True, 'date': ref.strftime('%Y-%m-%d'), 'groups': out})


def _conf_opt_generation_page(family):
    """Renderiza a confirmação de Opção pré-preenchida para um grupo
    contraparte × mercadoria da reference date (linhas no layout do Anexo I
    da macro legada de opções — 16 colunas)."""
    if not session.get('authenticated'):
        return redirect(url_for('pages_blueprint.sign_in_page'))
    ds = (request.args.get('date') or '').strip()
    acr = (request.args.get('acronym') or '').strip()
    merc = (request.args.get('mercadoria') or '').strip().upper()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()

    picked = _conf_pick_optcomm(ref, acr, merc, family)
    if not picked:
        return ('Nenhuma operação elegível para essa confirmação '
                '(contraparte {} × {} em {}).'.format(acr, merc, ref.strftime('%d/%m/%Y')), 404)

    first = picked[0][0]
    rows, warnings = [], []
    for deal, subj in picked:
        ua = str(deal.get('UnderlyingAsset') or '').strip()
        ticker = _CONF_TICKER_MAP.get(ua, ua)
        fator = _conf_to_float((subj or {}).get('fator'))
        strike = _conf_to_float(deal.get('Strike'))
        # Preço de Exercício = strike × Fator Conversão (mesma regra da Taxa
        # Forward do Termo; a macro usava strike_confirmation com o factor).
        strike_fmt = _conf_fmt_num(strike * (fator if fator else 1.0)) if strike is not None \
            else str(deal.get('Strike') or '').strip()
        premium = _conf_to_float(str(deal.get('Premium') or '').replace('-', ''))
        f_ini = _parse_date_any(deal.get('FixingStartDate'))
        f_fim = _parse_date_any(deal.get('FixingEndDate'))
        bullet = bool(f_ini and f_fim and f_ini == f_fim)
        direction = str(deal.get('Direction') or '').strip().upper()
        instrument = str(deal.get('Instrument') or '').upper()
        rows.append({
            'num':       str(deal.get('Deal') or '').strip(),
            'tipo':      'Venda' if 'PUT' in instrument else 'Compra',
            'forma':     'Europeia',
            'ticker':    ticker,
            'bolsa':     'PLATTS' if family in ('platts', 'brl-platts') else str((subj or {}).get('bolsa') or '').strip(),
            'qtd':       _conf_fmt_num(str(deal.get('TotalNotional') or '').replace('-', ''), dec=None),
            'ptax':      _conf_fmt_date(deal.get('FXConvDate')),
            'comprador': 'Parte B' if direction.startswith('S') else 'Parte A',
            'premio':    'R$ ' + _conf_fmt_num(premium, dec=2) if premium is not None
                         else str(deal.get('Premium') or '').strip() or 'Não Aplicável',
            'dtPremio':  _conf_fmt_date(deal.get('SpotDate')) or 'Não Aplicável',
            'strike':    strike_fmt,
            # Asiática: janela de verificação preenchida, Data de Exercício N/A;
            # bullet (europeia de fato): só a Data de Exercício (= fixing end).
            'dtIni':     'Não Aplicável' if bullet else _conf_fmt_date(deal.get('FixingStartDate')),
            'dtFim':     'Não Aplicável' if bullet else _conf_fmt_date(deal.get('FixingEndDate')),
            'dtExerc':   _conf_fmt_date(deal.get('FixingEndDate')) if bullet else 'Não Aplicável',
            'dtVenc':    _conf_fmt_date(deal.get('SettlementDate')),
        })
        if subj is None:
            warnings.append('Ativo {} sem cadastro no Subjacente (bolsa/fator ausentes).'.format(ua))

    cgd_txt = _conf_cgd_lookup(first)
    if not cgd_txt:
        warnings.append('CGD não cadastrado no Reference Data — preencha no painel.')

    trade_date = first.get('TradeDate') or ref
    conf = {
        'ref_date':     ref.strftime('%Y-%m-%d'),
        'cgd_date':     cgd_txt,
        'parteb_nome':  str(first.get('Client') or '').strip(),
        'parteb_cnpj':  _conf_fmt_cnpj(first.get('TaxID')),
        'data_neg':     _conf_fmt_date(trade_date),
        'data_extenso': _conf_date_extenso(trade_date),
        'mercadoria':   merc,
        'acronym':      acr,
        'rows':         rows,
        'warnings':     warnings,
    }
    return render_template(_CONF_OPT_FAMILY_TEMPLATES[family][0], conf=conf)


@blueprint.route('/confirmation/opt-comm/strike-usd')
def confirmation_optcomm_strike_usd():
    return _conf_opt_generation_page('strike-usd')


@blueprint.route('/api/confirmation/opt-comm/save', methods=['POST'])
def api_conf_optcomm_save():
    """Salva a confirmação de Opção (Word + PDF + XML) no Electronic Inventory
    e grava o numeroContrato na coluna FepWeb ID — mesmo fluxo do NDF Comm."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    payload = request.get_json(silent=True) or {}
    family = (payload.get('family') or 'strike-usd').strip()
    if family not in _CONF_OPT_FAMILY_TEMPLATES:
        return jsonify({'success': False, 'message': 'Template not available for this family yet.'}), 400
    fields = payload.get('fields') or {}
    rows = [r for r in (payload.get('rows') or []) if isinstance(r, dict)]
    if not rows:
        return jsonify({'success': False, 'message': 'No operations to save.'}), 400
    # CGD é cláusula do documento ("ambos firmados entre as Partes em <data>"):
    # sem ela a confirmação sai com a lacuna em branco e vai assim para a
    # contraparte. Trava no servidor, não só no painel — o POST é público para
    # qualquer sessão autenticada.
    if not str(fields.get('cgd_date') or '').strip():
        return jsonify({'success': False, 'error': 'missing_cgd',
                        'message': 'Data do CGD não cadastrada para esta contraparte. '
                                   'Cadastre o CGD no Reference Data (ou preencha o campo '
                                   'Data do CGD no painel) antes de salvar a confirmação.'}), 400

    acr = str(payload.get('acronym') or '').strip() or 'CONFIRMATION'
    merc = str(payload.get('mercadoria') or '').strip()
    conf = {
        'ref_date':     str(payload.get('date') or '').strip(),
        'cgd_date':     str(fields.get('cgd_date') or '').strip(),
        'parteb_nome':  str(fields.get('parteb_nome') or '').strip(),
        'parteb_cnpj':  str(fields.get('parteb_cnpj') or '').strip(),
        'data_neg':     str(fields.get('data_neg') or '').strip(),
        'data_extenso': str(fields.get('data_extenso') or '').strip(),
        'acronym':      acr,
        'mercadoria':   merc,
        'rows':         rows,
        'warnings':     [],
    }

    try:
        from apps.pages.confirmation_pdfs import opcao_pdf
        pdf_bytes = opcao_pdf(conf)
    except ImportError:
        return jsonify({'success': False,
                        'message': 'reportlab is not installed — run pip install -r requirements.txt.'}), 500
    except Exception:
        log.error('[conf] PDF build failed:\n%s', traceback.format_exc())
        return jsonify({'success': False, 'message': 'PDF generation failed.'}), 500

    doc_html = render_template(_CONF_OPT_FAMILY_TEMPLATES[family][0],
                               conf=conf, doc_only=True)

    ref = _parse_date_any(payload.get('date')) or _parse_date_any(conf['data_neg']) or datetime.now()
    # Pasta da contraparte no Electronic Inventory (mesma árvore do upload
    # manual) — ver api_conf_ndfcomm_save.
    client_dir = _ei_resolve_client_dir(conf['parteb_nome'] or acr, create=True)
    dir_path = os.path.join(client_dir, 'Confirmations',
                            ref.strftime('%Y'), _ei_month_folder(ref.strftime('%m')),
                            ref.strftime('%d'), 'Commodities Options')
    if len(rows) == 1 and str(rows[0].get('num') or '').strip():
        base = '{} - {} - CONFIRMAÇÃO DE OPERAÇÕES DE DERIVATIVOS nº {}'.format(
            acr, merc, str(rows[0]['num']).strip())
    else:
        base = '{} - {} - CONFIRMAÇÃO DE OPERAÇÕES DE DERIVATIVOS - {}'.format(
            acr, merc, ref.strftime('%Y%m%d'))
    base = _ei_sanitize(base)

    try:
        os.makedirs(_ei_long_path(dir_path), exist_ok=True)
        candidate, n = base, 0
        while os.path.exists(_ei_long_path(os.path.join(dir_path, candidate + '.doc'))) or \
                os.path.exists(_ei_long_path(os.path.join(dir_path, candidate + '.pdf'))):
            n += 1
            candidate = '{} ({})'.format(base, n)
        doc_path = os.path.join(dir_path, candidate + '.doc')
        pdf_path = os.path.join(dir_path, candidate + '.pdf')
        with open(_ei_long_path(doc_path), 'w', encoding='utf-8') as fh:
            fh.write(doc_html)
        with open(_ei_long_path(pdf_path), 'wb') as fh:
            fh.write(pdf_bytes)

        # XML do contrato: tipoOperacao Option, numeroContrato com prefixo
        # Opt_Comm — o resto do padrão (valores, moedas, datas) é o do NDF.
        xml_files, numero_contrato, xml_warns, fep_updated = [], '', [], 0
        picked = _conf_pick_optcomm(ref, acr, merc, family)
        if picked:
            numero_contrato, xml_str, xml_warns = _conf_ndf_xml(
                picked, merc, ref, tipo='Option', prefixo='Opt_Comm')
            # Mesmo nome-base do .doc/.pdf: os três arquivos da confirmação
            # ficam juntos na listagem da pasta. O numeroContrato continua
            # dentro do XML (é ele que o FepWeb lê), só não nomeia mais o
            # arquivo — com vários deals ele era genérico
            # (NDF_Comm_YYYYMMDD_MERC) e não dizia de qual confirmação era.
            xbase = candidate
            xcand, xn = xbase, 0
            while os.path.exists(_ei_long_path(os.path.join(dir_path, xcand + '.xml'))):
                xn += 1
                xcand = '{} ({})'.format(xbase, xn)
            xml_path = os.path.join(dir_path, xcand + '.xml')
            with open(_ei_long_path(xml_path), 'w', encoding='utf-8') as fh:
                fh.write(xml_str)
            xml_files.append(xml_path)
            fep_updated = _conf_pc_set_fepweb([d.get('Deal') for d, _s in picked],
                                              numero_contrato)
        else:
            xml_warns = ['XML não gerado: nenhuma operação com status Success no grupo.']
    except Exception as exc:
        log.error('[conf] save failed:\n%s', traceback.format_exc())
        return jsonify({'success': False, 'message': 'Could not write to the Inventory share: ' + str(exc)}), 500

    ref_state = _parse_date_any(payload.get('date')) or ref
    with _cache_lock:
        state = _conf_state_load(ref_state, 'opt-comm')
        state[_conf_key(acr, merc, family)] = {
            'status': 'Generated', 'doc': doc_path, 'pdf': pdf_path,
            'saved_by': session.get('user_sid', ''),
            'saved_at': datetime.now().strftime('%d/%m/%Y %H:%M:%S'),
            'checks': {}, 'validated_by': '', 'validated_at': '',
        }
        _conf_state_save(ref_state, state, 'opt-comm')

    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Confirmation Saved', 'Opt Comm',
                         '{} · {} ({} op{})'.format(acr, merc, len(rows),
                                                    '' if len(rows) == 1 else 's'))
    validate_url = ('/confirmation/opt-comm/validate?date=' + ref_state.strftime('%Y-%m-%d')
                    + '&acronym=' + quote(acr) + '&mercadoria=' + quote(merc)
                    + '&family=' + quote(family))
    return jsonify({'success': True, 'files': [doc_path, pdf_path] + xml_files,
                    'numero_contrato': numero_contrato,
                    'fepweb_updated': fep_updated,
                    'warnings': xml_warns,
                    'validate_url': validate_url})


@blueprint.route('/api/confirmation/opt-comm/pdf')
def api_conf_optcomm_pdf():
    """Preview inline do PDF salvo da confirmação de Opção."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    _ref, _key, entry, err = _conf_state_entry_or_404(request.args, 'opt-comm')
    if err:
        return err
    pdf_path = (entry or {}).get('pdf') or ''
    if not pdf_path or not os.path.isfile(pdf_path):
        return ('PDF não encontrado no Inventory ({}).'.format(pdf_path), 404)
    return send_file(pdf_path, mimetype='application/pdf', as_attachment=False,
                     download_name=os.path.basename(pdf_path))


