@blueprint.route('/api/confirmation/opt-fxo/validate', methods=['POST'])
def api_conf_optfxo_validate():
    """Marca a confirmação de Opção de Câmbio como Success após o checklist."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    payload = request.get_json(silent=True) or {}
    ref, key, entry, err = _conf_state_entry_or_404(payload, 'opt-fxo')
    if err:
        return jsonify({'success': False, 'message': err[0]}), err[1]
    checks = payload.get('checks') or {}
    if not checks or not all(bool(v) for v in checks.values()):
        return jsonify({'success': False,
                        'message': 'Todos os itens do checklist precisam ser confirmados.'}), 400
    with _cache_lock:
        state = _conf_state_load(ref, 'opt-fxo')
        entry = state.get(key) or entry
        entry['status'] = 'Success'
        entry['checks'] = {str(k): True for k in checks}
        entry['validated_by'] = session.get('user_sid', '')
        entry['validated_at'] = datetime.now().strftime('%d/%m/%Y %H:%M:%S')
        state[key] = entry
        _conf_state_save(ref, state, 'opt-fxo')
    acr, merc = (key.split('|') + ['', ''])[:2]
    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Confirmation Validated', 'Opt FXO', '{} · {}'.format(acr, merc))
    return jsonify({'success': True, 'status': 'Success'})


# ==============================================================================
# NEW DEALS — MONITOR
# Visão por produto × status das operações importadas na reference date. Os
# caches de New Deals já são particionados por dia (YYYYMMDD_*.json), então o
# histórico "dia a dia" vem do próprio layout de arquivos — mudar a reference
# date apenas lê os arquivos daquele dia, nada precisa ser re-persistido.
# ==============================================================================

# Catálogo dos cards (ordem de exibição). 'dirs' são os caminhos relativos ao
# NEW_DEALS_CACHE_ROOT que alimentam o card (variantes de grafia incluídas).
# 'soon' = produto ainda sem desenvolvimento — o card aparece como placeholder,
# mas se um dia o diretório ganhar arquivos os números passam a contar sozinhos.
_NDM_CARDS = [
    {'key': 'ndf-commodities',    'label': 'NDF Commodities',     'url': '/new_deals-ndf-commodities',    'dirs': ('NDF/Commodities',),                          'les': ('JPM', 'LAW')},
    {'key': 'ndf-fwdstart',       'label': 'NDF FWD Start',       'url': '/new_deals-ndf-fwdstart',       'dirs': ('NDF/FWD Start', 'NDF/FwdStart'),             'les': ('JPM', 'MGT', 'LAW')},
    {'key': 'ndf-otherpublisher', 'label': 'NDF Other Publisher', 'url': '/new_deals-ndf-otherpublisher', 'dirs': ('NDF/OtherPublisher', 'NDF/Other Publisher'), 'les': ('JPM', 'MGT', 'LAW')},
    {'key': 'ndf-vanilla',        'label': 'NDF Vanilla',         'url': '/new_deals-ndf-vanilla',        'dirs': ('NDF/Vanilla',),                              'les': ('JPM', 'MGT', 'LAW')},
    {'key': 'opt-commodities',    'label': 'Commodities Options', 'url': '/new_deals-opt-commodities',    'dirs': ('Option/Commodities',),                       'les': ('JPM', 'LAW')},
    {'key': 'opt-fxo',            'label': 'FX Options',          'url': '/new_deals-opt-fxo',            'dirs': ('Option/FXO',),                               'les': ('JPM', 'LAW')},
    {'key': 'opt-equity',         'label': 'Equity Options',      'url': None, 'soon': True,              'dirs': ('Option/Equity', 'Option/Equities'),          'les': ('JPM', 'ATA')},
    {'key': 'swap-equities',      'label': 'Swap Equities',       'url': None, 'soon': True,              'dirs': ('Swap/Equities',),                            'les': ('JPM', 'ATA')},
    {'key': 'swap-cem',           'label': 'Swap CEM',            'url': None, 'soon': True,              'dirs': ('Swap/CEM',),                                 'les': ('JPM', 'LAW')},
    {'key': 'intrag-ndf',         'label': 'Intrag NDF',          'url': '/intrag-ndf',                   'dirs': ('Intrag/NDF',),                               'les': ('LAW', 'ATA')},
    {'key': 'intrag-option',      'label': 'Intrag Option',       'url': '/intrag-option',                'dirs': ('Intrag/Option',),                            'les': ('LAW', 'ATA')},
]

_NDM_JPM_RE = re.compile(r'J\.?P\.?\s*MORGAN', re.IGNORECASE)
# Produtos cuja entidade intragrupo é o fundo Atacama — a perna-espelho
# (Client = Banco) conta como ATA em vez de LAW.
_NDM_ATA_DIRS = {'Option/Equity', 'Option/Equities', 'Swap/Equities'}
# NDFs genéricos (têm coluna LE e não têm perna-espelho da Lawton nos caches):
# neles LAW = operação CONTRA a Lawton, não Client = Banco.
_NDM_GENERIC_NDF_DIRS = {'NDF/FWD Start', 'NDF/FwdStart',
                         'NDF/OtherPublisher', 'NDF/Other Publisher',
                         'NDF/Vanilla'}


def _ndm_deal_le(pkey, d):
    """Entidade (LE) de uma linha do monitor, para os subitens dos cards.
    Intrag: pelo portfolio code — INTRAGJP552 = LAW, INTRAGJP633 = ATA
    (Intrag NDF grava 'portfolio_code', Intrag Option grava 'portfolio').
    NDFs genéricos (Vanilla/Other Pub/FWD Start): LE = MGT → MGT;
    Client com LAWTON → LAW (operação contra a Lawton); resto → JPM. O teste
    "Client = Banco" não serve aqui: o nome da MGT no RefData também casa com
    J.P. Morgan, então as linhas JPM×MGT cairiam em LAW indevidamente.
    Demais produtos B3: linha cujo Client é o Banco J.P. Morgan é a
    perna-espelho da entidade intragrupo (ATA nos produtos de equities, LAW
    nos demais); o resto é registro do Banco → JPM."""
    if pkey.startswith('Intrag'):
        code = str(d.get('portfolio_code') or d.get('portfolio') or '').strip().upper()
        return {'INTRAGJP552': 'LAW', 'INTRAGJP633': 'ATA'}.get(code, 'ATA')
    cl = str(d.get('Client') or '')
    if pkey in _NDM_GENERIC_NDF_DIRS:
        if str(d.get('LE') or '').strip().upper() == 'MGT':
            return 'MGT'
        return 'LAW' if 'LAWTON' in cl.upper() else 'JPM'
    if _NDM_JPM_RE.search(cl):
        return 'ATA' if pkey in _NDM_ATA_DIRS else 'LAW'
    return 'JPM'


@blueprint.route('/new-deals-monitor')
def new_deals_monitor():
    if not session.get('authenticated'):
        return redirect(url_for('pages_blueprint.sign_in_page'))
    return render_template('pages/new-deals-monitor.html', segment='new-deals-monitor',
                           today=datetime.now().strftime('%Y-%m-%d'))


def _ndm_monitor_snapshot(ref):
    """(cards, conf_cards) do Monitor na reference date — exatamente a estrutura
    que a página consome. Está fora do endpoint de propósito: o e-mail diário de
    pendências lê daqui, e assim não existe uma segunda contagem para divergir
    do que o usuário vê na tela."""
    want = ref.strftime('%Y%m%d')

    # Um único walk: agrupa os arquivos DA DATA por produto (caminho sem os
    # níveis de ano/mês), contando linhas por Status e por LE (_ndm_deal_le).
    found, found_les = {}, {}
    if os.path.isdir(NEW_DEALS_CACHE_ROOT):
        for root, _dirs, files in os.walk(NEW_DEALS_CACHE_ROOT):
            for fname in files:
                if not fname.endswith('.json') or fname[:8] != want:
                    continue
                rel = os.path.relpath(root, NEW_DEALS_CACHE_ROOT).replace('\\', '/')
                pkey = '/'.join([p for p in rel.split('/') if not p.isdigit()][:2])
                try:
                    with open(os.path.join(root, fname), encoding='utf-8') as fh:
                        data = json.load(fh)
                except Exception:
                    continue
                bucket = found.setdefault(pkey, Counter())
                les    = found_les.setdefault(pkey, Counter())
                for d in (data if isinstance(data, list) else [data]):
                    if isinstance(d, dict):
                        # Intrag entries carry lowercase 'status' — without the
                        # fallback every intrag deal counted as 'New' forever.
                        st = str(d.get('Status') or d.get('status') or 'New').strip() or 'New'
                        if st == 'Canceled':      # cancelado via API: fora das métricas
                            continue
                        bucket[st] += 1
                        les[_ndm_deal_le(pkey, d)] += 1

    cards, claimed = [], set()
    for c in _NDM_CARDS:
        agg, agg_le = Counter(), Counter()
        for dkey in c['dirs']:
            if dkey in found:
                agg.update(found[dkey])
                agg_le.update(found_les.get(dkey, {}))
                claimed.add(dkey)
        cards.append({
            'key': c['key'], 'label': c['label'], 'url': c['url'],
            'soon': bool(c.get('soon')), 'total': sum(agg.values()),
            'statuses': dict(agg),
            # Lista ordenada (não dict) para o front preservar a ordem dos LEs
            'les': [{'le': k, 'count': agg_le.get(k, 0)} for k in c.get('les', ())],
        })
    # "e etc": qualquer produto com arquivos na data que não está no catálogo
    # (ex.: Swap Rates / Swap Commodities) ganha um card genérico no fim.
    for pkey in sorted(found):
        if pkey in claimed:
            continue
        agg = found[pkey]
        cards.append({
            'key': 'extra-' + pkey.lower().replace('/', '-').replace(' ', '-'),
            'label': pkey.replace('/', ' '), 'url': None, 'soon': False,
            'total': sum(agg.values()), 'statuses': dict(agg),
        })

    # Zona Confirmations: segregação contraparte × mercadoria (pontas
    # banco/lawton fora). O ciclo aqui é o DA CONFIRMAÇÃO (New → Generated →
    # Success), não o status dos deals: cada grupo segregado conta 1 no chip do
    # seu estágio. NDF Commodities, Commodities Options e FX Options têm o
    # fluxo completo; os demais produtos só contam a segregação.
    conf_groups, _deal_statuses, _conf_deal_total = _conf_ndfcomm_groups(ref)
    conf_state = _conf_state_load(ref)
    conf_statuses = Counter()
    for g in conf_groups:
        entry = conf_state.get(_conf_key(g['acronym'], g['mercadoria'], g['family'])) or {}
        conf_statuses[entry.get('status') or 'New'] += 1
    conf_cards = [{
        'key': 'conf-ndf-commodities', 'label': 'NDF Commodities',
        'url': '/new_deals-ndf-commodities', 'soon': False,
        'total': len(conf_groups), 'statuses': dict(conf_statuses),
        'groups': [{'label': '{} · {}'.format(g['acronym'], g['mercadoria']),
                    'family': g['family'], 'count': g['count']} for g in conf_groups],
    }]

    def _conf_option_card(key, label, url, cache_dirs, suffix, by_commodity):
        if isinstance(cache_dirs, str):
            cache_dirs = (cache_dirs,)
        groups = {}
        for cache_dir in cache_dirs:
            fp = os.path.join(cache_dir, ref.strftime('%Y'), ref.strftime('%m'),
                              ref.strftime('%Y%m%d') + suffix)
            if not os.path.isfile(fp):
                continue
            try:
                with open(fp, encoding='utf-8') as fh:
                    data = json.load(fh)
            except Exception:
                data = []
            for d in (data if isinstance(data, list) else []):
                if not isinstance(d, dict):
                    continue
                if str(d.get('Status') or '').strip() == 'Canceled':
                    continue
                client = str(d.get('Client') or '').strip()
                if _CONF_INTERNAL_RE.search(client):
                    continue
                acr = str(d.get('Acronym') or '').strip() or client or '(sem contraparte)'
                merc = str(d.get('Commodities') or '').strip().upper() if by_commodity else ''
                g = groups.setdefault((acr, merc), {'acronym': acr, 'mercadoria': merc, 'count': 0})
                g['count'] += 1
        ordered = sorted(groups.values(), key=lambda g: (g['acronym'], g['mercadoria']))
        return {
            'key': key, 'label': label, 'url': url, 'soon': False,
            'total': len(ordered),
            'statuses': ({'New': len(ordered)} if ordered else {}),
            'groups': [{'label': ('{} · {}'.format(g['acronym'], g['mercadoria'])
                                  if g['mercadoria'] else g['acronym']),
                        'count': g['count']} for g in ordered],
        }

    # FWD Start tem duas grafias de pasta em produção (FwdStart / FWD Start),
    # como nos cards de B3 — o card soma as duas. Segregação só por contraparte
    # (NDF de moeda não tem mercadoria).
    conf_cards.append(_conf_option_card(
        'conf-ndf-fwdstart', 'NDF FWD Start', '/new_deals-ndf-fwdstart',
        (os.path.join(NEW_DEALS_CACHE_ROOT, 'NDF', 'FwdStart'),
         os.path.join(NEW_DEALS_CACHE_ROOT, 'NDF', 'FWD Start')),
        '_ndffwdstart.json', False))
    # Commodities Options: ciclo próprio da confirmação, igual ao NDF Comm.
    opt_groups, _opt_deal_statuses, _opt_total = _conf_optcomm_groups(ref)
    opt_state = _conf_state_load(ref, 'opt-comm')
    opt_statuses = Counter()
    for g in opt_groups:
        entry = opt_state.get(_conf_key(g['acronym'], g['mercadoria'], g['family'])) or {}
        opt_statuses[entry.get('status') or 'New'] += 1
    conf_cards.append({
        'key': 'conf-opt-commodities', 'label': 'Commodities Options',
        'url': '/new_deals-opt-commodities', 'soon': False,
        'total': len(opt_groups), 'statuses': dict(opt_statuses),
        'groups': [{'label': '{} · {}'.format(g['acronym'], g['mercadoria']),
                    'family': g['family'], 'count': g['count']} for g in opt_groups],
    })
    # FX Options: ciclo próprio da confirmação também (Vanilla × Asian), igual
    # ao Commodities Options — a segregação aqui é por contraparte × moeda base.
    fxo_groups, _fxo_deal_statuses, _fxo_total = _conf_optfxo_groups(ref)
    fxo_state = _conf_state_load(ref, 'opt-fxo')
    fxo_statuses = Counter()
    for g in fxo_groups:
        entry = fxo_state.get(_conf_key(g['acronym'], g['mercadoria'], g['family'])) or {}
        fxo_statuses[entry.get('status') or 'New'] += 1
    conf_cards.append({
        'key': 'conf-opt-fxo', 'label': 'FX Options',
        'url': '/new_deals-opt-fxo', 'soon': False,
        'total': len(fxo_groups), 'statuses': dict(fxo_statuses),
        'groups': [{'label': '{} · {}'.format(g['acronym'], g['mercadoria']),
                    'family': g['family'], 'count': g['count']} for g in fxo_groups],
    })

    return cards, conf_cards


@blueprint.route('/api/new-deals/monitor')
def api_new_deals_monitor():
    if not session.get('authenticated'):
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    ds = (request.args.get('date') or '').strip()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()
    cards, conf_cards = _ndm_monitor_snapshot(ref)
    return jsonify({'success': True, 'date': ref.strftime('%Y-%m-%d'),
                    'cards': cards, 'conf_cards': conf_cards})


# ──────────────────────────────────────────────────────────────────────────
# Deals Monitor — e-mail diário de pendências (19h00 e 19h30)
# ──────────────────────────────────────────────────────────────────────────
# Varre os cards do Monitor da data e manda para a mesa o que ainda NÃO está
# 100% Success. Um card entra na lista quando tem operação (total > 0) e pelo
# menos uma fora de Success; a quantidade é `total - Success`, que é exatamente
# o que sobra de ação na tela.
#
# As contagens saem de _ndm_monitor_snapshot, o MESMO código que alimenta a
# página — de propósito. Uma segunda contagem própria do e-mail divergiria da
# tela no primeiro ajuste de regra, e a mesa passaria a não confiar em nenhuma
# das duas.

# Tipo (zona do Monitor) × produto × detalhe de cada card. As zonas são as três
# da tela: Registration (B3), Confirmation e Intrag.
_NDM_TAXONOMY = {
    'ndf-commodities':    ('NDF', 'Commodities'),
    'ndf-fwdstart':       ('NDF', 'FWD Start'),
    'ndf-otherpublisher': ('NDF', 'Other Publisher'),
    'ndf-vanilla':        ('NDF', 'Vanilla'),
    'opt-commodities':    ('Option', 'Commodities'),
    'opt-fxo':            ('Option', 'FX'),
    'opt-equity':         ('Option', 'Equity'),
    'swap-equities':      ('Swap', 'Equities'),
    'swap-cem':           ('Swap', 'CEM'),
    # Intrag não tem sub-variante: o tipo da linha já diz Intrag, e repetir a
    # palavra na coluna Detail não acrescenta nada.
    'intrag-ndf':         ('NDF', '—'),
    'intrag-option':      ('Option', '—'),
    'intrag-swap':        ('Swap', '—'),
}
_NDM_TYPE_ORDER = ['Registration', 'Confirmation', 'Intrag']


def _ndm_card_taxonomy(card, zone):
    """(tipo, produto, detalhe) de um card. Produto fora do catálogo (os cards
    'Others', que nascem sozinhos quando aparece um diretório novo no cache)
    cai no label do próprio card, para nunca sumir do e-mail por falta de
    cadastro."""
    key = str(card.get('key') or '')
    if key in _NDM_TAXONOMY:
        product, detail = _NDM_TAXONOMY[key]
    elif key.startswith('conf-') and key[5:] in _NDM_TAXONOMY:
        product, detail = _NDM_TAXONOMY[key[5:]]
    else:
        label = str(card.get('label') or key or '—').strip()
        parts = label.split(None, 1)
        product, detail = (parts[0], parts[1]) if len(parts) == 2 else (label, '—')
    return zone, product, detail


def _ndm_pending_blocks(ref):
    """Blocos (um por tipo) com os cards que ainda não estão 100% Success.
    Retorna (blocks, grand_total); lista vazia = nada pendente na data."""
    cards, conf_cards = _ndm_monitor_snapshot(ref)
    by_type = {}
    for zone, group in (('Registration', cards), ('Confirmation', conf_cards)):
        for card in group:
            # Intrag é zona própria na tela, mas vem junto dos cards de B3.
            z = 'Intrag' if str(card.get('key') or '').startswith('intrag-') else zone
            total = int(card.get('total') or 0)
            statuses = card.get('statuses') or {}
            # ⚠️ Success comparado SEM caixa: o cache do Intrag grava o status em
            # minúsculo ('success'), e contar só a grafia 'Success' deixaria os
            # cards de Intrag eternamente pendentes no aviso — falso alarme
            # diário é o jeito mais rápido de a mesa parar de ler o e-mail.
            success = sum(int(v or 0) for k, v in statuses.items()
                          if str(k).strip().lower() == 'success')
            pending = total - success
            if total <= 0 or pending <= 0:
                continue
            _z, product, detail = _ndm_card_taxonomy(card, z)
            # Chips do card, na ordem em que aparecem: diz de QUE ação a
            # pendência é (New, Amend, Generated…), não só quantas são.
            breakdown = ', '.join(
                '{} {}'.format(v, str(k)[:1].upper() + str(k)[1:])
                for k, v in statuses.items()
                if str(k).strip().lower() != 'success' and v)
            by_type.setdefault(_z, []).append(
                {'product': product, 'detail': detail, 'pending': pending,
                 'breakdown': breakdown, 'total': total, 'success': success})
    blocks = []
    for t in _NDM_TYPE_ORDER + sorted(k for k in by_type if k not in _NDM_TYPE_ORDER):
        rows = by_type.get(t)
        if not rows:
            continue
        rows.sort(key=lambda r: (-r['pending'], r['product'], r['detail']))
        blocks.append({'type': t, 'rows': rows,
                       'total': sum(r['pending'] for r in rows)})
    return blocks, sum(b['total'] for b in blocks)


_NDM_PENDING_DEFAULT_TO = 'brazil.otc.ops@jpmorgan.com'
_NDM_PENDING_RECIPIENTS_FILE = os.path.join(_DAILY_METRIC_DIR,
                                            'deals_monitor_pending_recipients.json')
# Dois disparos por dia. O segundo é lembrete: quem não tratou às 19h00 leva o
# aviso de novo às 19h30, já com a lista atualizada.
_NDM_PENDING_TIMES = os.getenv('DEALS_MONITOR_PENDING_TIMES', '19:00,19:30')


def _load_ndm_pending_recipients():
    """TO/CC do aviso, do card Deals Monitor do Control Panel. Sem nada salvo
    vale o default da mesa — assim a rotina já funciona no pull, antes de
    alguém abrir o Control Panel."""
    try:
        with open(_NDM_PENDING_RECIPIENTS_FILE, encoding='utf-8') as fh:
            d = json.load(fh)
        if isinstance(d, dict) and (d.get('to') or d.get('cc')):
            return {'to': d.get('to', '') or '', 'cc': d.get('cc', '') or ''}
    except Exception:
        pass
    return {'to': _NDM_PENDING_DEFAULT_TO, 'cc': ''}


def _save_ndm_pending_recipients(to, cc):
    os.makedirs(_DAILY_METRIC_DIR, exist_ok=True)
    with open(_NDM_PENDING_RECIPIENTS_FILE, 'w', encoding='utf-8') as fh:
        json.dump({'to': to or '', 'cc': cc or ''}, fh, ensure_ascii=False, indent=2)


def _send_ndm_pending_email(ref, to_list, cc_list):
    """Envia o aviso de pendências do Monitor. Retorna True, 'empty' (nada
    pendente — não manda e-mail) ou a mensagem de erro."""
    from email.mime.image import MIMEImage
    try:
        blocks, grand_total = _ndm_pending_blocks(ref)
        if not blocks:
            log.info('[deals-monitor] %s: nada pendente, e-mail não enviado',
                     ref.strftime('%Y-%m-%d'))
            return 'empty'
        ref_fmt = ref.strftime('%d/%m/%Y')
        html = render_template('pages/email-template-deals-monitor.html',
                               ref_date_fmt=ref_fmt, blocks=blocks,
                               grand_total=grand_total, current_year=datetime.now().year)
        msg = MIMEMultipart('related')
        msg['Subject'] = 'Pending Action - Deals Monitor'
        msg['From'] = SHARED_MAILBOX
        if to_list:
            msg['To'] = ', '.join(to_list)
        if cc_list:
            msg['Cc'] = ', '.join(cc_list)
        alt = MIMEMultipart('alternative')
        alt.attach(MIMEText('Please view this report in HTML.', 'plain', 'utf-8'))
        alt.attach(MIMEText(html, 'html', 'utf-8'))
        msg.attach(alt)
        logo_path = _get_logo_path()
        if logo_path:
            with open(logo_path, 'rb') as f:
                limg = MIMEImage(f.read())
            limg.add_header('Content-ID', '<otc_logo>')
            limg.add_header('Content-Disposition', 'inline', filename='logo.png')
            msg.attach(limg)
        _attach_email_gradient(msg)
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as server:
            server.sendmail(SHARED_MAILBOX, to_list + cc_list, msg.as_string())
        log.info('[deals-monitor] aviso de pendências enviado — ref=%s · %d item(ns) '
                 'em %d tipo(s) · to=%s cc=%s', ref.strftime('%Y-%m-%d'), grand_total,
                 len(blocks), to_list, cc_list)
        return True
    except Exception as e:                                  # noqa: BLE001
        log.error('[deals-monitor] aviso de pendências FALHOU:\n%s', traceback.format_exc())
        return '{}: {}'.format(type(e).__name__, e)


@blueprint.route('/api/control-panel/deals-monitor/recipients', methods=['GET', 'POST'])
def api_cp_deals_monitor_recipients():
    """TO/CC do aviso diário, do card Deals Monitor. Salvar vazio nos dois
    campos volta ao default da mesa em vez de desligar a rotina em silêncio."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    if request.method == 'GET':
        return jsonify({'success': True, **_load_ndm_pending_recipients()})
    payload = request.get_json(silent=True) or {}
    try:
        _save_ndm_pending_recipients((payload.get('to') or '').strip(),
                                     (payload.get('cc') or '').strip())
    except Exception as e:                                  # noqa: BLE001
        log.error('[deals-monitor] save recipients failed:\n%s', traceback.format_exc())
        return jsonify({'success': False, 'error': '{}: {}'.format(type(e).__name__, e)}), 500
    return jsonify({'success': True})


@blueprint.route('/api/control-panel/deals-monitor/run', methods=['POST'])
def api_cp_deals_monitor_run():
    """Dispara o aviso na hora, sem esperar os horários agendados."""
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    payload = request.get_json(silent=True) or {}
    ds = (payload.get('date') or '').strip()
    try:
        ref = datetime.strptime(ds[:10], '%Y-%m-%d') if ds else datetime.now()
    except ValueError:
        ref = datetime.now()
    rec = _load_ndm_pending_recipients()
    to_list, cc_list = _parse_emails(rec['to']), _parse_emails(rec['cc'])
    if not (to_list or cc_list):
        return jsonify({'success': False,
                        'error': 'Nenhum destinatário salvo. Preencha o TO antes de rodar.'}), 400
    result = _send_ndm_pending_email(ref, to_list, cc_list)
    if result == 'empty':
        return jsonify({'success': True,
                        'message': 'Nothing pending on the Deals Monitor — no e-mail sent.'})
    if result is not True:
        return jsonify({'success': False, 'error': 'E-mail failed: {}'.format(result)}), 500
    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Deals Monitor Sent', 'Control Panel',
                         'Pending Action e-mailed ({})'.format(ref.strftime('%Y-%m-%d')))
    return jsonify({'success': True,
                    'message': 'Pending Action enviado para {} destinatário(s).'.format(
                        len(to_list) + len(cc_list))})


_ndm_pending_scheduler_started = False
_ndm_pending_scheduler_lock = threading.Lock()
_NDM_PENDING_SENT_FILE = os.path.join(_DAILY_METRIC_DIR, 'deals_monitor_pending_sent.json')


def _ndm_pending_claim_slot(slot):
    """Reserva um disparo ('YYYY-MM-DD 19:00') EM DISCO. True = ninguém tinha
    reservado e o e-mail pode sair; False = já foi.

    A trava em memória não basta: com o reloader do Werkzeug ligado o módulo é
    importado em DOIS processos, cada um com o seu scheduler, e a mesa receberia
    o aviso duas vezes. Persistência de deal é idempotente e sobrevive a isso —
    e-mail não. O arquivo guarda só os últimos disparos, para não crescer."""
    with _cache_lock:
        try:
            with open(_NDM_PENDING_SENT_FILE, encoding='utf-8') as fh:
                sent = json.load(fh)
            if not isinstance(sent, list):
                sent = []
        except (IOError, OSError, json.JSONDecodeError):
            sent = []
        if slot in sent:
            return False
        sent.append(slot)
        try:
            os.makedirs(_DAILY_METRIC_DIR, exist_ok=True)
            _atomic_write_json(_NDM_PENDING_SENT_FILE, sorted(sent)[-16:])
        except Exception:                                   # noqa: BLE001
            log.warning('[deals-monitor] não consegui gravar o controle de disparo:\n%s',
                        traceback.format_exc())
        return True


def _ndm_pending_times():
    """Horários do dia em (hh, mm), ordenados. Entrada inválida cai no padrão —
    um typo na variável de ambiente não pode matar o aviso."""
    out = []
    for part in str(_NDM_PENDING_TIMES or '').split(','):
        part = part.strip()
        if not part:
            continue
        try:
            hh, mm = (int(x) for x in part.split(':')[:2])
        except (ValueError, TypeError):
            continue
        if 0 <= hh <= 23 and 0 <= mm <= 59:
            out.append((hh, mm))
    return sorted(set(out)) or [(19, 0), (19, 30)]


def _ndm_pending_disparar(slot, fired):
    """Manda o aviso de um slot, se ninguém já mandou. True quando o slot era
    deste processo (reivindicado agora)."""
    if not _ndm_pending_claim_slot(slot):
        return False
    rec = _load_ndm_pending_recipients()
    to_list, cc_list = _parse_emails(rec['to']), _parse_emails(rec['cc'])
    if not (to_list or cc_list):
        log.warning('[deals-monitor] sem destinatário configurado — aviso pulado')
        return True
    res = _send_ndm_pending_email(fired, to_list, cc_list)
    # O resultado vai para o log SEMPRE: quando o aviso não chega, a primeira
    # pergunta é se ele não foi enviado ou se não havia pendência ('empty'), e
    # sem esta linha não dava para saber.
    log.info('[deals-monitor] aviso de %s (BRT): %s', slot,
             'enviado' if res is True else res)
    return True


def _ndm_pending_catch_up(times):
    """Slots de HOJE que já passaram e ninguém reivindicou.

    A instância do time é reiniciada várias vezes por dia (o reloader fica
    desligado, então todo pull pede restart). Subindo depois das 19h30, o loop
    dormia até o dia seguinte e o aviso do dia simplesmente não saía — sem erro
    nenhum no log. O arquivo de claim é que garante que isto não vire e-mail
    repetido quando há mais de um restart."""
    now = _br_now()
    for hh, mm in times:
        cand = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if cand > now:
            continue
        slot = '{} {:02d}:{:02d}'.format(now.strftime('%Y-%m-%d'), hh, mm)
        try:
            if _ndm_pending_disparar(slot, now):
                log.info('[deals-monitor] aviso de %s recuperado no start '
                         '(processo subiu depois do horário)', slot)
        except Exception:                              # noqa: BLE001
            log.error('[deals-monitor] catch-up de %s falhou:\n%s',
                      slot, traceback.format_exc())


def _ndm_pending_scheduler_loop():
    times = _ndm_pending_times()
    _ndm_pending_catch_up(times)
    while True:
        try:
            now = _br_now()
            # Próximo horário de hoje que ainda não passou; se todos passaram,
            # o primeiro de amanhã.
            nxt = None
            for hh, mm in times:
                cand = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
                if cand > now:
                    nxt = cand
                    break
            if nxt is None:
                hh, mm = times[0]
                nxt = (now + timedelta(days=1)).replace(hour=hh, minute=mm,
                                                        second=0, microsecond=0)
            time.sleep(max(1.0, (nxt - now).total_seconds()))
            fired = _br_now()
            slot = '{} {:02d}:{:02d}'.format(fired.strftime('%Y-%m-%d'),
                                             nxt.hour, nxt.minute)
            if not _ndm_pending_disparar(slot, fired):
                time.sleep(60)
        except Exception:
            log.error('[deals-monitor] scheduler error:\n%s', traceback.format_exc())
            time.sleep(60)


def _ndm_pending_start_scheduler():
    global _ndm_pending_scheduler_started
    with _ndm_pending_scheduler_lock:
        if _ndm_pending_scheduler_started:
            return
        _ndm_pending_scheduler_started = True
    threading.Thread(target=_ndm_pending_scheduler_loop,
                     name='deals-monitor-pending-scheduler', daemon=True).start()
    log.info('[deals-monitor] scheduler de pendências iniciado (%s BRT · '
             'agora são %s no servidor / %s em Brasília)',
             ', '.join('{:02d}:{:02d}'.format(h, m) for h, m in _ndm_pending_times()),
             datetime.now().strftime('%H:%M'), _br_now().strftime('%H:%M'))


try:
    _ndm_pending_start_scheduler()
except Exception:
    log.warning('[deals-monitor] could not start the pending scheduler')


def _find_generic_nd_deal(cfg, deal_name, client_name=None):
    """Locate a deal by Deal (+optional Client) across the product's cache files.
    Returns (file_path, list_index) or (None, None)."""
    base = cfg['dir']
    if not os.path.isdir(base):
        return None, None
    for root, _dirs, files in os.walk(base):
        for fname in sorted(files):
            if not fname.endswith(cfg['suffix']):
                continue
            fpath = os.path.join(root, fname)
            try:
                with open(fpath, 'r', encoding='utf-8') as fh:
                    deals = json.load(fh)
                if not isinstance(deals, list):
                    deals = [deals]
                for i, deal in enumerate(deals):
                    if deal.get('Deal', '') == deal_name and (client_name is None or deal.get('Client', '') == client_name):
                        return fpath, i
            except Exception:
                continue
    return None, None


@blueprint.route('/api/new-deals/<product>/cache', methods=['POST'])
def api_generic_nd_save_cache(product):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    data = request.get_json(silent=True)
    if not data:
        return jsonify({"success": False, "message": "No data provided"}), 400

    try:
        ref_date = datetime.strptime(data.get('TradeDate', ''), '%d/%m/%Y')
    except (ValueError, TypeError):
        ref_date = datetime.now()

    dir_path = os.path.join(cfg['dir'], ref_date.strftime('%Y'), ref_date.strftime('%m'))
    os.makedirs(dir_path, exist_ok=True)
    file_path = os.path.join(dir_path, ref_date.strftime('%Y%m%d') + cfg['suffix'])

    with _cache_lock:
        if os.path.exists(file_path):
            try:
                with open(file_path, 'r', encoding='utf-8') as fh:
                    deals = json.load(fh)
                if not isinstance(deals, list):
                    deals = [deals]
            except (json.JSONDecodeError, ValueError):
                deals = []
        else:
            deals = []

        deal_name   = data.get('Deal', '').strip()
        client_name = data.get('Client', '').strip()
        existing_idx = next((i for i, d in enumerate(deals)
                             if deal_name
                             and d.get('Deal', '').strip() == deal_name
                             and d.get('Client', '').strip() == client_name), None)
        if existing_idx is not None:
            deals[existing_idx] = data
        else:
            deals.append(data)
        _atomic_write_json(file_path, deals)

    return jsonify({"success": True, "deal": data.get('Deal', '')})


def _generic_nd_reenrich(deals, refmap_cache):
    """Preenche SPN/Client/TaxID de deals importados com contraparte faltante
    cujo Acronym (End Counterparty) passou a existir no RefData — o cadastro
    feito depois do import só corrigia o DOM da página; ao sair e voltar, o
    cache em disco ainda tinha os campos vazios (linha sem badge e sem
    cliente). Retorna True se algo mudou (o caller persiste o arquivo).
    refmap_cache: dict de 1 posição para construir o mapa por acronym só uma
    vez por request."""
    changed = False
    for deal in deals:
        if not isinstance(deal, dict):
            continue
        if str(deal.get('SPN', '') or '').strip():
            continue
        acr = str(deal.get('Acronym', '') or '').strip().upper()
        if not acr:
            continue
        if 'map' not in refmap_cache:
            refmap_cache['map'] = _fxo_refdata_by_accronym()
        # Mapping Legal Entity × Accronym: o accronym gravado pode identificar a
        # LE (é o caso do End Counterparty que é nome de book interno, importado
        # antes de a linha existir). Quando ele identifica, a LE gravada estava
        # errada — veio da Settlement Location — e é corrigida aqui, junto com a
        # contraparte da entidade, sem precisar de novo pull da API.
        #
        # Só `le_map` entra na busca da contraparte. Caindo para a LE gravada no
        # deal (que veio da Settlement Location, a NOSSA perna) um cliente sem
        # accronym cadastrado era re-enriquecido como a própria JPMorgan — o
        # mesmo erro de _ndf_deal_from_api, aqui aplicado a quem já está no
        # arquivo.
        le_map = _ndf_le_from_accronym(acr)
        rec = _ndf_ref_by_accronym(refmap_cache['map'], acr, le_map)
        if not rec:
            if le_map and le_map != str(deal.get('LE', '') or '').strip().upper():
                deal['LE'] = le_map
                changed = True
            continue
        if le_map and le_map != str(deal.get('LE', '') or '').strip().upper():
            deal['LE'] = le_map
        deal['SPN'] = str(rec.get('SPN', '') or '')
        deal['Client'] = rec.get('COUNTERPARTY', '') or ''
        deal['TaxID'] = rec.get('TAX ID', '') or ''
        ref_acr = str(rec.get('FX CASH ACCRONYM', '') or '').strip()
        if ref_acr:
            deal['Acronym'] = ref_acr
        changed = True
    return changed


@blueprint.route('/api/new-deals/<product>/cache/search', methods=['POST'])
def api_generic_nd_search_cache(product):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    filters = (request.get_json(silent=True) or {}).get('filters', [])
    matched, refmap_cache = [], {}
    if os.path.isdir(cfg['dir']):
        for root, _dirs, files in os.walk(cfg['dir']):
            for fname in sorted(files):
                if not fname.endswith(cfg['suffix']):
                    continue
                fpath = os.path.join(root, fname)
                try:
                    with open(fpath, 'r', encoding='utf-8') as fh:
                        deals = json.load(fh)
                    if not isinstance(deals, list):
                        deals = [deals]
                    # Contraparte cadastrada depois do import → persiste o
                    # enriquecimento, senão a linha volta vazia a cada visita.
                    if _generic_nd_reenrich(deals, refmap_cache):
                        with _cache_lock:
                            _atomic_write_json(fpath, deals)
                    for deal in deals:
                        if _deal_matches(deal, filters):
                            matched.append(deal)
                except Exception:
                    continue
    return jsonify({"success": True, "deals": matched})


@blueprint.route('/api/new-deals/<product>/cache/<deal_id>', methods=['PATCH'])
def api_generic_nd_update_cache(product, deal_id):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    client  = request.args.get('client')
    updates = request.get_json(silent=True)
    if not updates:
        return jsonify({"success": False, "message": "No data provided"}), 400

    file_path, _ = _find_generic_nd_deal(cfg, deal_id, client)
    if file_path is None:
        return jsonify({"success": False, "message": "Deal not found"}), 404

    with _cache_lock:
        try:
            with open(file_path, 'r', encoding='utf-8') as fh:
                deals = json.load(fh)
        except (json.JSONDecodeError, ValueError):
            deals = []
        idx = next((i for i, d in enumerate(deals)
                    if d.get('Deal') == deal_id and (client is None or d.get('Client', '') == client)), None)
        if idx is None:
            return jsonify({"success": False, "message": "Deal not found"}), 404
        deals[idx].update(updates)
        _atomic_write_json(file_path, deals)
        updated_deal = deals[idx].copy()

    # Vanilla / Other Publisher contra o Lawton alimentam a Intrag NDF no
    # layout "Instrucao NDF Moeda" quando o Status vira Success (FWD Start fora
    # — o strike só existe na strike set date, quando rebooka como vanilla).
    if str(updates.get('Status', '')) == 'Success':
        if product in ('vanilla', 'other-publishers') and \
                'LAWTON' in (updated_deal.get('Client', '') or '').upper():
            try:
                _save_intrag_ndf_moeda_entry(updated_deal)
            except Exception as exc:
                log.error('[ND %s] Intrag moeda save failed for deal=%r: %s',
                          product, deal_id, exc)
        _generic_nd_pc_trigger(product, updated_deal)       # → pending confirmation

    _fields = {k: v for k, v in updates.items() if k not in ('Maker', 'Checker', '_client')}
    if _fields:
        if 'Status' in _fields:
            # The 'Sent' transition is already announced by the 'Sent to B3'
            # notification emitted from send-conecta — skip the redundant
            # 'Status Updated' entry so the bell shows a single item per send.
            if str(_fields.get('Status', '')) != 'Sent':
                _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                                     'Status Updated', cfg['label'], deal_id + ' → ' + str(_fields.get('Status', '')) + _nd_token(updated_deal.get('TradeDate')))
        else:
            _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                                 'Deal Updated', cfg['label'], deal_id + ' (' + ', '.join(_fields.keys()) + ')' + _nd_token(updated_deal.get('TradeDate')))
    return jsonify({"success": True})


@blueprint.route('/api/new-deals/<product>/cache/<deal_id>', methods=['DELETE'])
def api_generic_nd_delete_cache(product, deal_id):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    client = request.args.get('client')
    file_path, _ = _find_generic_nd_deal(cfg, deal_id, client)
    if file_path is None:
        return jsonify({"success": False, "message": "Deal not found"}), 404

    with _cache_lock:
        try:
            with open(file_path, 'r', encoding='utf-8') as fh:
                deals = json.load(fh)
        except (json.JSONDecodeError, ValueError):
            deals = []
        idx = next((i for i, d in enumerate(deals)
                    if d.get('Deal') == deal_id and (client is None or d.get('Client', '') == client)), None)
        if idx is None:
            return jsonify({"success": False, "message": "Deal not found"}), 404
        removed = deals.pop(idx)
        _atomic_write_json(file_path, deals)

    _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                         'Deal Deleted', cfg['label'], deal_id + _nd_token((removed or {}).get('TradeDate')))
    return jsonify({"success": True})


@blueprint.route('/api/new-deals/<product>/cache/bulk-delete', methods=['POST'])
def api_generic_nd_bulk_delete_cache(product):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    data  = request.get_json(silent=True)
    pairs = data.get('pairs', []) if data else []
    if not pairs:
        return jsonify({"success": False, "message": "No pairs provided"}), 400

    pair_set = {(p.get('deal', ''), p.get('client', '')) for p in pairs}
    file_pairs = {}
    for deal_name, client_name in pair_set:
        fp, _ = _find_generic_nd_deal(cfg, deal_name, client_name)
        if fp:
            file_pairs.setdefault(fp, set()).add((deal_name, client_name))

    deleted = 0
    for fp, pairs_in_file in file_pairs.items():
        with _cache_lock:
            try:
                with open(fp, 'r', encoding='utf-8') as fh:
                    deals = json.load(fh)
            except (json.JSONDecodeError, ValueError):
                deals = []
            if not isinstance(deals, list):
                deals = [deals]
            before = len(deals)
            deals  = [d for d in deals if (d.get('Deal', ''), d.get('Client', '')) not in pairs_in_file]
            deleted += before - len(deals)
            _atomic_write_json(fp, deals)

    not_found = len(pair_set) - deleted
    if deleted > 0:
        _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                             'Bulk Delete', cfg['label'],
                             str(deleted) + ' deal' + ('s' if deleted != 1 else '') + ' deleted')
    return jsonify({"success": True, "deleted": deleted, "not_found": not_found})


@blueprint.route('/api/new-deals/<product>/cache/bulk-patch', methods=['POST'])
def api_generic_nd_bulk_patch_cache(product):
    if not session.get('authenticated'):
        return jsonify({"success": False, "message": "Not authenticated"}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({"success": False, "message": "Unknown product"}), 404

    data    = request.get_json(silent=True)
    patches = data.get('patches', []) if data else []
    if not patches:
        return jsonify({"success": False, "message": "No patches provided"}), 400

    file_patches = {}
    for p in patches:
        deal_id = p.get('deal_id', '')
        client  = p.get('client', '')
        updates = p.get('updates', {})
        if not deal_id or not updates:
            continue
        fp, _ = _find_generic_nd_deal(cfg, deal_id, client)
        if fp:
            file_patches.setdefault(fp, []).append((deal_id, client, updates))

    updated = 0
    for fp, file_ops in file_patches.items():
        with _cache_lock:
            try:
                with open(fp, 'r', encoding='utf-8') as fh:
                    deals = json.load(fh)
            except (json.JSONDecodeError, ValueError):
                deals = []
            success_deals = []
            for deal_id, client, updates in file_ops:
                idx = next((i for i, d in enumerate(deals)
                            if d.get('Deal') == deal_id and (not client or d.get('Client', '') == client)), None)
                if idx is not None:
                    deals[idx].update(updates)
                    updated += 1
                    if str(updates.get('Status', '')) == 'Success':
                        success_deals.append(deals[idx].copy())
            _atomic_write_json(fp, deals)
        for d in success_deals:
            _generic_nd_pc_trigger(product, d)              # → pending confirmation

    if updated > 0:
        _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                             'Bulk Update', cfg['label'],
                             str(updated) + ' deal' + ('s' if updated != 1 else '') + ' updated')
    return jsonify({"success": True, "updated": updated})


# ──────────────────────────────────────────────────────────────────────────
# GENERIC NDF (FWD Start / Other Publisher) — send-conecta (TER files)
# ──────────────────────────────────────────────────────────────────────────
# Same positional TER layout as ndf-commodities, with the FX-NDF field rules.
# Lines are split into THREE files by participant entity:
#   • client is the Banco J.P. Morgan → the LAWTON-side leg → *_LAWTON file
#     (participant 00041007) — mirrors the ndf-commodities convention;
#   • else LE = MGT → *_MGT file (participant 04880006);
#   • else → *_BANCO file (participant 73760009).
# Counterparty account follows the LE matrix used on the page previews.

# Athena publisher (feeder) → códigos B3: mapping publisher-ndf, tela Mapping.
def _ndf_publisher_row(publisher):
    """Linha do mapping publisher-ndf que casa o publisher.

    Duas passadas, nesta ordem:

    1. **Nome exato** — o PUBLISHER da linha igual ao publisher inteiro. Uma
       linha **sem** Match Tokens só casa aqui: é o texto completo, sem
       variação. É o que separa a linha 'PTAX' da 'PTAX|BRR|PTAX' — as duas
       existem e cada uma vale para o seu publisher exato.
    2. **Token** — só para linhas COM a coluna TOKENS preenchida, porque a
       Athena manda o publisher composto ('PTAX|USB|WMR|4' → REUTERS - WMR).

    Nada casando → {}.
    """
    p = (publisher or '').strip().upper()
    if not p:
        return {}
    rows = _mapping_rows('publisher-ndf')
    for r in rows:
        if str(r.get('PUBLISHER', '') or '').strip().upper() == p:
            return r
    for r in rows:
        for tok in re.split(r'[,;]', str(r.get('TOKENS', '') or '')):
            tok = tok.strip().upper()
            if tok and tok in p:
                return r
    return {}


# Valor da coluna NOTES que marca o feeder como BACEN — e, com isso, manda a
# operação para a página Vanilla em vez de Other Publisher.
_NDF_NOTES_BACEN = 'BACEN'


def _ndf_publisher_is_bacen(publisher):
    """True quando a linha do publisher no mapping tem NOTES = BACEN.

    É o que decide Vanilla × Other Publisher. Antes o teste era o literal
    `publisher.upper() != 'PTAX'` no roteamento da API, então qualquer variante
    ('PTAX|BRR|PTAX') caía em Other Publisher mesmo sendo PTAX do BACEN, e não
    havia como corrigir sem mexer no código. Agora quem decide é o cadastro.

    Publisher vazio conta como BACEN: é o default histórico do import, que
    tratava ausência de feeder como PTAX puro.
    """
    if not (publisher or '').strip():
        return True
    notes = str(_ndf_publisher_row(publisher).get('NOTES', '') or '').strip().upper()
    return notes == _NDF_NOTES_BACEN


def _ndf_publisher_codes(publisher):
    """Publisher → {'consulta': Fonte de Consulta, 'info': Tela ou Função de
    Consulta}. Publisher sem linha no mapping devolve {} (campos em branco)."""
    r = _ndf_publisher_row(publisher)
    if not r:
        return {}
    return {'consulta': str(r.get('FONTE CONSULTA', '') or '').strip(),
            'info': str(r.get('TELA CONSULTA', '') or '').strip()}


def _ndf_publisher_fonte_info(publisher):
    """Fonte de Informação do TER, 4 chars alinhados à direita. Sem linha no
    mapping = 1, que era o comportamento de quando isso era hardcoded."""
    fi = str(_ndf_publisher_row(publisher).get('FONTE INFO', '') or '').strip() or '1'
    return fi.rjust(4)

def _moeda_num_code(iso):
    """ISO 3-letter → B3 3-digit currency code (mapping Currency Base, SIMBOLO →
    CODIGO DE CADASTRO). Unknown/blank → ''. Lê pelo loader do mapping, que
    cacheia por mtime: edição na tela vale na requisição seguinte."""
    m = {}
    for r in _mapping_rows('currency-base'):
        sym = str(r.get('SIMBOLO') or '').strip().upper()
        code = str(r.get('CODIGO DE CADASTRO') or '').strip()
        if sym and code and sym not in m:
            m[sym] = code
    return m.get(str(iso or '').strip().upper(), '')


_anbima_hols_cache = None


def _anbima_holidays():
    global _anbima_hols_cache
    if _anbima_hols_cache is None:
        try:
            with open(os.path.join(_B3_DATA_DIR, 'anbima.json'), encoding='utf-8') as fh:
                _anbima_hols_cache = {(x.get('date') if isinstance(x, dict) else x)
                                      for x in json.load(fh)}
        except (IOError, json.JSONDecodeError):
            _anbima_hols_cache = set()
    return _anbima_hols_cache


def _anbima_biz_diff(start_dt, end_dt):
    """ANBIMA business days in (start, end] — the 'diferença de dias úteis'."""
    if not start_dt or not end_dt or end_dt <= start_dt:
        return 0
    hols, n, cur = _anbima_holidays(), 0, start_dt
    while cur < end_dt:
        cur += timedelta(days=1)
        if cur.weekday() < 5 and cur.strftime('%Y-%m-%d') not in hols:
            n += 1
    return n


def _anbima_add_biz(start_dt, n):
    """start advanced by n ANBIMA business days."""
    if not start_dt:
        return None
    hols, cur, left = _anbima_holidays(), start_dt, n
    while left > 0:
        cur += timedelta(days=1)
        if cur.weekday() < 5 and cur.strftime('%Y-%m-%d') not in hols:
            left -= 1
    return cur


@blueprint.route('/api/new-deals/<product>/send-conecta', methods=['POST'])
def api_generic_nd_send_conecta(product):
    if not session.get('authenticated'):
        return jsonify({'ok': False, 'error': 'Not authenticated'}), 401
    if product not in ('fwd-start', 'other-publishers'):
        return jsonify({'ok': False, 'error': 'send-conecta not available for this product'}), 404
    is_fwd = product == 'fwd-start'
    prefix = 'FWDSTART' if is_fwd else 'OTHERPUBLISHER'

    deals = (request.get_json(silent=True) or {}).get('deals', [])
    if not deals:
        return jsonify({'ok': False, 'error': 'No deals provided'}), 400

    today = datetime.today().strftime('%Y%m%d')

    def _s(v):
        return re.sub(r'<[^>]+>', '', str(v or '')).strip()

    def _pos(s, width, align='left', fill=' '):
        s = str(s or '')[:width]
        return s.rjust(width, fill) if align == 'right' else s.ljust(width, fill)

    def _znum(val, int_digits, dec_digits):
        """Zero-padded positional number: int_digits + dec_digits chars."""
        try:
            from decimal import Decimal
            d = abs(Decimal(str(val).replace(',', '')))
            ip = int(d)
            fp = int(((d - ip) * (10 ** dec_digits)).to_integral_value())
            return str(ip).zfill(int_digits) + str(fp).zfill(dec_digits)
        except Exception:
            return '0' * (int_digits + dec_digits)

    def _d8(v):
        dt = _parse_date_any(_s(v))
        return dt.strftime('%Y%m%d') if dt else ''

    def _is_jpm(c):
        return bool(re.search(r'J\.?P\.?\s*MORGAN', c.upper()))

    def _is_mgt(c):
        return 'MGT' in c.upper()

    def _is_lawton(c):
        return 'LAWTON' in c.upper()

    buckets = {'BANCO': [], 'LAWTON': [], 'MGT': []}
    counts = Counter()
    for deal in deals:
        if str(deal.get('Status', '') or '').strip() == 'Canceled':
            continue                    # cancelado via API: fora dos arquivos
        client   = _s(deal.get('Client', ''))
        le       = _s(deal.get('LE', '')).upper()
        deal_id  = _s(deal.get('Deal', ''))
        publisher = _s(deal.get('Publisher', ''))
        qty_ccy  = _s(deal.get('QuantityCurrency', '')).upper()
        oth_ccy  = _s(deal.get('OtherQuantityCurrency', '')).upper()
        # O flag de asiático NÃO vem do TradeType: ele é derivado das datas de
        # fixing logo abaixo (asian_fix), para o arquivo não depender de um
        # rótulo que pode ter vindo do XLSX ou de uma edição manual.

        # Entity bucket + participant / counterparty accounts
        if 'LAWTON' in le:                        # LE Lawton: parte Lawton × banco JPM
            bucket, participant, cpty = 'LAWTON', '00041007', '73760009'
        elif _is_jpm(client):                     # Lawton-side mirror leg
            bucket, participant = 'LAWTON', '00041007'
            cpty = '04880006' if le == 'MGT' else '73760009'
        else:
            bucket = 'MGT' if le == 'MGT' else 'BANCO'
            participant = '04880006' if le == 'MGT' else '73760009'
            if _is_lawton(client):
                cpty = '00041007'
            elif le == 'MGT':
                cpty = '73760009' if _is_jpm(client) else '04880109'
            else:
                cpty = '04880006' if _is_mgt(client) else '73760102'
        taxid = '' if ('LAWTON' in le or _is_jpm(client) or _is_lawton(client) or _is_mgt(client)) \
            else re.sub(r'[.\-\/]', '', _s(deal.get('TaxID', '')))

        last_fix_dt = _parse_date_any(_s(deal.get('LastFixingDate', '')))
        settl_dt    = _parse_date_any(_s(deal.get('SettlementDate', '')))
        biz_diff    = _anbima_biz_diff(last_fix_dt, settl_dt)

        strike_set_dt = _parse_date_any(_s(deal.get('StrikeSetDate', '')))
        fixacao_dt    = _anbima_add_biz(strike_set_dt, biz_diff) if strike_set_dt else None

        # Fonte de Informação: coluna do mapping publisher-ndf (PTAX puro = 0,
        # demais feeders = 1). Boletim: no OP sai em branco; no FWD Start segue
        # a fonte (0 → 3, senão 1).
        fonte_info = _ndf_publisher_fonte_info(publisher)
        boletim    = ('3' if fonte_info.strip() == '0' else '1') if is_fwd else ' '

        # Valor Base / Quantidade: inteiro alinhado à direita em 14 + '00'. Estas
        # páginas mandam a coluna como Notional (só o NDF Comm usa TotalNotional)
        # — aceita os dois. O valor gravado é US ('{:,.2f}'), mas uma edição
        # manual pode chegar em BR; quando os dois separadores aparecem, quem
        # define o decimal é o que vem por último. Sem isso, '5.158.000,00' não
        # parseia e o campo sai com 16 zeros em silêncio.
        notional_s = (_s(deal.get('TotalNotional', '')) or _s(deal.get('Notional', ''))).replace(' ', '')
        if ',' in notional_s and '.' in notional_s:
            notional_s = (notional_s.replace('.', '').replace(',', '.')
                          if notional_s.rfind(',') > notional_s.rfind('.')
                          else notional_s.replace(',', ''))
        elif notional_s.count('.') > 1:
            notional_s = notional_s.replace('.', '')     # 5.158.000 — dois pontos só podem ser milhar
        else:
            notional_s = notional_s.replace(',', '')     # US, o formato que a aplicação grava
        try:
            qty_int = int(round(float(notional_s)))
            qty_str = str(qty_int).rjust(14, '0') + '00'
        except Exception:
            qty_str = '0' * 16

        fix_start = _d8(deal.get('FirstFixingDate', ''))
        fix_end   = _d8(deal.get('LastFixingDate', ''))
        # Asiático exige JANELA de fixing: primeira E última preenchidas e
        # DIFERENTES. First fixing vazio (fixing único) ou datas iguais = vanilla.
        # A regra antiga só testava a igualdade das duas, então o first vazio
        # caía em 'A' — um fixing único ia para a B3 como média asiática.
        asian_fix  = bool(fix_start and fix_end and fix_start != fix_end)
        # Vanilla: Data de Fixing do Ativo Subjacente = a data do fixing único
        # (a última preenchida). Asiático deixa em branco — as datas da janela
        # vão nas linhas de verificação.
        fix_single = '' if asian_fix else (fix_end or fix_start)
        # Other Publisher: a Data de Fixing do Ativo Subjacente vai SEMPRE em
        # branco (as 8 posições do campo preenchidas com espaço). Só o FWD Start
        # continua mandando a data do fixing único. `tipo_media` não depende
        # deste campo — sai de `asian_fix` —, então zerar aqui não muda a
        # classificação da operação.
        if not is_fwd:
            fix_single = ''
        tipo_media = 'A' if asian_fix else 'N'

        if is_fwd:
            taxa_termo   = _pos('', 20)
            cot_venc     = str(biz_diff)[:1] or '0'
            fonte_cons   = ''
            tela_cons    = ''
            cot_rs_usd   = ''
            cot_paridade = ''
            data_aval    = ''
            termo_flag   = 'S'
            forma_atu    = 'V'
            valor_perc   = _znum(_s(deal.get('StrikeSetOffset', '')) or '0', 4, 8)
        else:
            # Weak currencies quote inverted vs BRL: 1/rate arredondado pelas
            # casas da aba Currency Codes (Inverse Decimals) da tela Mapping.
            rate_raw = _fxo_num(_s(deal.get('Rate', '')))
            _inv = _mapping_ccy_maps()[2]
            if rate_raw and qty_ccy in _inv:
                rate_val = round(1.0 / rate_raw, _inv[qty_ccy])
            else:
                rate_val = rate_raw
            taxa_termo   = _znum(rate_val if rate_val is not None else '0', 12, 8)
            cot_venc     = ' '
            pub = _ndf_publisher_codes(publisher)
            fonte_cons   = pub.get('consulta', '')
            tela_cons    = pub.get('info', '')
            cot_rs_usd   = '1'
            cot_paridade = '3'
            data_aval    = _d8(deal.get('LastFixingDate', ''))
            termo_flag   = 'N'
            forma_atu    = ' '
            valor_perc   = (_znum(_s(deal.get('StrikeSetOffset', '')), 4, 8)
                            if _s(deal.get('StrikeSetOffset', '')) else _pos('', 12))

        dir_code = '0' if _s(deal.get('Direction', '')).upper() == 'BUY' else '1'
        my_number = str(random.randint(1000000000, 9999999999))

        # OP com BRL fixed: inverte as moedas — a estrangeira vira a Moeda de
        # Referência e o BRL a Moeda Cotada.
        brl_fixed = (not is_fwd) and _s(deal.get('IsBRRFixed', '')).upper() == 'YES'
        moeda_ref, moeda_cot = (oth_ccy, qty_ccy) if brl_fixed else (qty_ccy, oth_ccy)

        line = (
            _pos('TER  ', 5)                         +  # ID do Sistema
            _pos('1', 1)                             +  # ID Tipo de Linha
            _pos('0001', 4)                          +  # Código Operação
            _pos(my_number, 10)                      +  # Meu Número
            _pos(participant, 8)                     +  # Lançamento do Participante
            _pos(dir_code, 1)                        +  # Papel
            _pos('', 14)                             +  # CPF/CNPJ Cliente Parte
            _pos(cpty, 8)                            +  # Contraparte
            _pos(taxid, 14)                          +  # CPF/CNPJ Contraparte
            _pos('S', 1)                             +  # Contrato Global
            _pos('2', 20, 'right')                   +  # Classe do Ativo Subjacente
            _pos(fonte_info, 4)                      +  # Fonte de Informação
            _pos(_moeda_num_code(moeda_ref), 3)      +  # Moeda de Referência
            _pos(_moeda_num_code(moeda_cot), 3)      +  # Moeda Cotada
            _pos(cot_venc, 1)                        +  # Cotação para o Vencimento
            _pos(qty_str, 16)                        +  # Valor Base / Quantidade
            _pos('', 10)                             +  # Código do Ativo Subjacente
            _pos(taxa_termo, 20)                     +  # Taxa a Termo (R$/Moeda)
            _pos(fix_single, 8)                      +  # Data de Fixing do Ativo Subjacente
            _pos(_d8(deal.get('TradeDate', '')), 8)  +  # Data de Operação
            _pos(_d8(deal.get('SettlementDate', '')), 8) +  # Data de Vencimento
            _pos(boletim, 1)                         +  # Boletim
            _pos(' ', 1)                             +  # Tipo de Cotação
            _pos('', 8)                              +  # Data de Fixing da Moeda
            _pos('', 1)                              +  # Cross Rate na Avaliação?
            _pos(fonte_cons, 1)                      +  # Fonte de Consulta
            _pos(tela_cons, 8, 'right')              +  # Tela ou Função de Consulta
            _pos('', 8)                              +  # Praça de Negociação
            _pos('', 8)                              +  # Horário de Consulta
            _pos(cot_rs_usd, 1)                      +  # Cotação Taxa de Câmbio R$/USD
            _pos(cot_paridade, 1)                    +  # Cotação Paridade
            _pos(data_aval, 8)                       +  # Data de Avaliação
            _pos('', 10)                             +  # Código da Paridade Cross
            _pos('', 8)                              +  # Data de Fixing da Paridade Cross
            _pos(termo_flag, 1)                      +  # Termo a Termo
            _pos(fixacao_dt.strftime('%Y%m%d') if fixacao_dt else '', 8) +  # Data de Fixação
            _pos(forma_atu, 1)                       +  # Forma de Atualização
            _pos(valor_perc, 12)                     +  # Valor / Percentual Negociado
            _pos((str(biz_diff)[:1] or '0') if is_fwd else ' ', 1) +  # Cotação para Fixing (OP: em branco)
            _pos('N', 1)                             +  # Atualizar Valor Base?
            _pos('', 12)                             +  # Cotação Inicial
            _pos('N', 1)                             +  # Ajustar Taxa
            _pos('', 1)                              +  # Responsável pelo Ajuste da Taxa
            _pos('', 8)                              +  # Data Inicial para Ajuste da Taxa
            _pos('', 8)                              +  # Data Final para Ajuste da Taxa
            _pos('', 1)                              +  # Limites
            _pos('', 14)                             +  # Superior (Paridade)
            _pos('', 14)                             +  # Inferior (Paridade)
            _pos('', 8)                              +  # Data de Liquidação do Prêmio
            _pos('', 1)                              +  # Prêmio a ser Pago Pelo
            _pos('', 16)                             +  # Valor do Prêmio
            _pos('', 1)                              +  # Modalidade de Liquidação
            _pos('', 1)                              +  # Prêmio em Moeda Estrangeira
            _pos('', 8)                              +  # Data de Fixing da Moeda do Prêmio
            _pos('S' if _s(deal.get('IsBRRFixed', '')).upper() == 'YES' else '', 1) +  # Taxa a Termo em Reais
            _pos('', 280)                            +  # Observação
            _pos(deal_id[-14:], 14, 'right')         +  # Código Identificador (right 14 of Deal)
            _pos(tipo_media, 1)                      +  # Tipo Média Asiático
            _pos(str(_anbima_biz_diff(
                _parse_date_any(_s(deal.get('FirstFixingDate', ''))),
                _parse_date_any(_s(deal.get('LastFixingDate', ''))))
                 + 1).zfill(3) if asian_fix else '000', 3)  # Qtde Datas Verificação
        )
        buckets[bucket].append(line)
        counts[bucket] += 1

    headers = {
        'BANCO':  _pos('TER  ', 5) + '0' + '0001' + 'JPMORGANBM' + ' ' * 10 + today + '00003',
        'LAWTON': _pos('TER  ', 5) + '0' + '0001' + 'INTRAGLAWTONFDO' + ' ' * 5 + today + '00003',
        'MGT':    _pos('TER  ', 5) + '0' + '0001' + 'MORGANBC' + ' ' * 12 + today + '00003',
    }

    generated = []
    try:
        os.makedirs(CONECTA_NEW_PATH, exist_ok=True)
        for bucket in ('BANCO', 'LAWTON', 'MGT'):
            if not buckets[bucket]:
                continue
            path = _unique_filepath(CONECTA_NEW_PATH, '{}_{}.txt'.format(prefix, bucket))
            with open(path, 'w', encoding='utf-8') as fh:
                fh.write('\n'.join([headers[bucket]] + buckets[bucket]))
            generated.append({'filename': os.path.basename(path), 'count': counts[bucket]})
        total = sum(counts.values())
        if total > 0:
            cfg = _generic_nd_cfg(product)
            _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                                 'Sent to B3', cfg['label'] if cfg else product,
                                 str(total) + ' deal' + ('' if total == 1 else 's') + ' sent')
        primary = generated[0]['filename'] if generated else ''
        return jsonify({'ok': True, 'filename': primary, 'count': total, 'files': generated})
    except Exception as exc:                            # noqa: BLE001
        return jsonify({'ok': False, 'error': str(exc)}), 500


# Status que ESPERAM retorno da B3: só esses viram 'Error' quando o deal não
# aparece no arquivo. Um deal em Approved/Pending ainda nem foi registrado, e um
# já Success não pode regredir por causa de um arquivo que já foi consumido.
_ND_MAPPING_ERRORABLE = {'New', 'Sent', 'Error'}


def _generic_nd_mapping_candidates(cfg, product, ref_date):
    """Deals da Reference Date que entram no mapping do arquivo de retorno.

    Sai do ARQUIVO DO DIA, não da tabela. A tabela mostra o resultado da última
    busca — mapear o que estava renderizado deixava para trás operações do mesmo
    dia que ninguém tinha filtrado.

    Entram todos os status, exceto:
      • 'Canceled' — cancelado na API, fora do fluxo;
      • já 'Success' COM B3 ID — não há o que mapear e uma segunda passada só
        poderia perder informação.
    Nas outras páginas o filtro antigo (New/Sent/Error) é mantido: o Vanilla é
    que é registrado por outra ferramenta, e por isso precisa olhar qualquer
    status."""
    ref = _parse_date_any(ref_date)
    if not ref:
        return []
    fpath = os.path.join(cfg['dir'], ref.strftime('%Y'), ref.strftime('%m'),
                         ref.strftime('%Y%m%d') + cfg['suffix'])
    if not os.path.isfile(fpath):
        return []
    try:
        with open(fpath, encoding='utf-8') as fh:
            deals = json.load(fh)
        if not isinstance(deals, list):
            deals = [deals]
    except (IOError, json.JSONDecodeError):
        return []

    out, seen = [], set()
    for d in deals:
        if not isinstance(d, dict):
            continue
        deal = str(d.get('Deal', '') or '').strip()
        if not deal:
            continue
        status = str(d.get('Status', '') or '').strip()
        if status == 'Canceled':
            continue
        if status == 'Success' and str(d.get('B3_ID', '') or '').strip():
            continue
        if product != 'vanilla' and status not in _ND_MAPPING_ERRORABLE:
            continue
        client = str(d.get('Client', '') or '').strip()
        key = (deal, client)
        if key in seen:
            continue
        seen.add(key)
        out.append({'Deal': deal, 'Client': client, 'Status': status})
    return out


@blueprint.route('/api/new-deals/<product>/mapping-b3', methods=['POST'])
def api_generic_nd_mapping_b3(product):
    """B3 return-file scan for the generic NDF pages — same logic as the
    ndf-commodities mapping. The TER files write the RIGHT-14 chars of the Deal
    as Código Identificador, so the return-line match uses that suffix."""
    if not session.get('authenticated'):
        return jsonify({'ok': False, 'error': 'Not authenticated'}), 401
    cfg = _generic_nd_cfg(product)
    if not cfg:
        return jsonify({'ok': False, 'error': 'Unknown product'}), 404

    data = request.get_json(silent=True) or {}
    # `ref_date` = campo Reference Date da página. Com ele a lista sai do ARQUIVO
    # DO DIA e não da tabela: a tabela mostra o resultado da última busca, então
    # mapear o que estava renderizado deixava de fora operações do mesmo dia que
    # ninguém tinha filtrado. `deals` continua aceito para chamadas com lista
    # explícita.
    sent_deals = (_generic_nd_mapping_candidates(cfg, product, data.get('ref_date'))
                  if data.get('ref_date') else data.get('deals', []))
    if not sent_deals:
        return jsonify({'ok': True, 'results': []})

    mapping         = {}
    files_to_delete = []
    try:
        if not os.path.isdir(RETURN_PATH):
            return jsonify({'ok': False, 'error': f'Return folder not found: {RETURN_PATH}'}), 400

        for fname in os.listdir(RETURN_PATH):
            fpath = os.path.join(RETURN_PATH, fname)
            if not os.path.isfile(fpath):
                continue
            try:
                with open(fpath, 'r', encoding='latin-1') as fh:
                    lines = fh.readlines()
                file_has_ter = False
                for line in lines[1:]:  # skip header row
                    line = line.strip()
                    if not line:
                        continue
                    # Sigla at chars 57-59 (1-based): only 'TER' (termo) lines
                    if line[56:59] != 'TER':
                        continue
                    file_has_ter = True
                    if 'EXECUCAO OK' not in line:
                        continue
                    parts = line.split(';')
                    if len(parts) < 2:
                        continue
                    b3_id = parts[1].strip()
                    for sd in sent_deals:
                        deal_text = sd.get('Deal', '')
                        if deal_text and deal_text not in mapping and deal_text[-14:] in line:
                            mapping[deal_text] = b3_id
                # Only delete return files that actually carried TER (NDF) lines
                if file_has_ter:
                    files_to_delete.append(fpath)
            except Exception:
                continue
    except Exception as exc:
        return jsonify({'ok': False, 'error': str(exc)}), 500

    results = []
    for sd in sent_deals:
        deal_text   = sd.get('Deal', '')
        client_name = sd.get('Client', '')
        if str(sd.get('Status', '') or '').strip() == 'Canceled':
            continue                    # cancelado via API: fora do mapping
        if deal_text and deal_text in mapping:
            b3_id      = mapping[deal_text]
            new_status = 'Success'
            updates    = {'Status': new_status, 'B3_ID': b3_id}
        else:
            b3_id = ''
            # Não achou no retorno: só vira 'Error' quem estava esperando
            # retorno. Agora que a varredura pega o dia inteiro em qualquer
            # status, marcar todo mundo derrubaria para Error operações que nem
            # sequer foram registradas ainda (Approved/Pending) — e, pior, um
            # Success sem B3 ID.
            prev = str(sd.get('Status', '') or '').strip()
            if prev and prev not in _ND_MAPPING_ERRORABLE:
                new_status = prev
                updates    = {}
            else:
                new_status = 'Error'
                updates    = {'Status': new_status}

        success_deal = None
        if deal_text and updates:
            file_path, idx = _find_generic_nd_deal(cfg, deal_text, client_name)
            if file_path is not None:
                with _cache_lock:
                    try:
                        with open(file_path, 'r', encoding='utf-8') as fh:
                            deals_list = json.load(fh)
                        deals_list[idx].update(updates)
                        _atomic_write_json(file_path, deals_list)
                        if new_status == 'Success':
                            success_deal = deals_list[idx].copy()
                    except Exception:
                        pass

        if success_deal is not None:
            # Vanilla / Other Publisher contra o Lawton → Intrag NDF (layout
            # "Instrucao NDF Moeda"), mesmo gatilho do update manual.
            if product in ('vanilla', 'other-publishers') and \
                    'LAWTON' in (success_deal.get('Client', '') or '').upper():
                try:
                    _save_intrag_ndf_moeda_entry(success_deal)
                except Exception as exc:
                    log.error('[MAPPING-%s] Intrag moeda save failed for deal=%r: %s',
                              product, deal_text, exc)
            _generic_nd_pc_trigger(product, success_deal)   # → pending confirmation

        # Só entra no resultado quem MUDOU. Varrendo o dia inteiro, a lista
        # passa a incluir deals que ficaram como estavam — contá-los inflaria o
        # "N deal(s) mapped" da notificação e os contadores da tela.
        if updates:
            results.append({
                'id':     deal_text,
                'deal':   deal_text,
                'b3_id':  b3_id,
                'status': new_status,
            })

    for fpath in files_to_delete:
        try:
            os.remove(fpath)
        except Exception:
            pass

    if results:
        _create_notification(session.get('user_sid', ''), session.get('user_name', ''),
                             'B3 Mapped', cfg['label'],
                             str(len(results)) + ' deal' + ('' if len(results) == 1 else 's') + ' mapped')
    return jsonify({'ok': True, 'results': results})


# ==============================================================================
# SUPPORT CENTER — TICKETS
# ==============================================================================
#
# Quem pode o quê (o storage não valida nada disso — é tudo decidido aqui,
# onde existe sessão):
#
#   ver        → o master vê todos; qualquer outro usuário vê só os próprios.
#   criar      → qualquer usuário autenticado. Requester, SID e status ('New')
#                vêm da SESSÃO, nunca do corpo do request.
#   status     → só o master. O requester é notificado a cada mudança.
#   due date   → só o master (regra do usuário: o prazo é do time, não de quem abre).
#   subject/description/priority/tags → o requester enquanto o ticket estiver
#                aberto, e o master sempre.
#   apagar     → o requester ou o master.
#   comentar   → o requester ou o master.
#
# Notificações: ticket novo → só o master (target_role='MASTER', que só o master
# tem). Mudança de status → só o requester (target_sid).
# ==============================================================================

_TICKETS_PAGE = 'Support'
_TICKET_OPS_CC = 'brazil.otc.ops@jpmorgan.com'


def _tk_session_user():
    return ((session.get('user_sid') or '').strip().upper(),
            (session.get('user_name') or '').strip(),
            (session.get('user_email') or '').strip())


def _tk_is_requester(ticket, sid):
    return (ticket.get('requester_sid') or '').upper() == (sid or '').upper()


def _tk_can_view(ticket, sid):
    return _session_is_master() or _tk_is_requester(ticket, sid)


def _tk_public(ticket, sid):
    """Ticket + os flags de permissão que a tela usa para habilitar controles.
    Calculados no servidor de propósito: a UI esconde o que o usuário não pode
    fazer, mas quem recusa de fato é o endpoint."""
    is_master = _session_is_master()
    mine = _tk_is_requester(ticket, sid)
    out = dict(ticket)
    out['agent_name'] = otc_tickets.AGENT_NAME
    out['can_edit_status'] = is_master
    out['can_edit_due'] = is_master
    out['can_edit_fields'] = is_master or (mine and ticket.get('status') not in otc_tickets.FINAL_STATUSES)
    out['can_delete'] = is_master or mine
    out['can_comment'] = is_master or mine
    out['is_requester'] = mine
    return out


def _tk_visible_tickets(sid):
    tickets = otc_tickets.list_all()
    if not _session_is_master():
        tickets = [t for t in tickets if _tk_is_requester(t, sid)]
    # Mais recente primeiro: o seq é monotônico, então ordena por ele e não pela
    # data (que é string e empata quando dois tickets nascem no mesmo segundo).
    tickets.sort(key=lambda t: t.get('seq') or 0, reverse=True)
    return tickets


def _tk_notify_master(actor_sid, actor_name, ticket):
    """Ticket novo → sino do master apenas. 'MASTER' não é papel de banco: é o
    valor que `_set_session` grava em user_role para os SIDs de `_MASTER_SIDS`,
    então nenhum outro usuário casa com esse target_role."""
    _create_notification(
        actor_sid, actor_name, 'New Ticket', _TICKETS_PAGE,
        '#{} — {}'.format(ticket.get('id') or '', ticket.get('subject') or ''),
        target_role='MASTER')


def _tk_notify_requester(actor_sid, actor_name, ticket, detail):
    """Atualização → sino do requester apenas. Se quem mexeu foi o próprio
    requester, não há o que avisar."""
    rsid = (ticket.get('requester_sid') or '').upper()
    if not rsid or rsid == (actor_sid or '').upper():
        return
    _create_notification(actor_sid, actor_name, 'Ticket Updated', _TICKETS_PAGE,
                         detail, target_sid=rsid)


def _tk_send_closed_email(ticket):
    """E-mail de encerramento: requester no To, a caixa de OTC Ops em cópia.
    Best-effort — devolve True ou a mensagem de erro. O ticket JÁ está gravado
    quando isto roda, então uma falha de SMTP (fora da rede JPM, por exemplo)
    não pode desfazer o encerramento; ela só é registrada no log."""
    from email.mime.image import MIMEImage
    to_addr = (ticket.get('requester_email') or '').strip()
    if not to_addr:
        log.warning('[tickets] %s closed without requester e-mail — no notice sent',
                    ticket.get('id'))
        return 'requester has no e-mail on file'
    try:
        html = render_template(
            'pages/email-template-ticket-closed.html',
            ticket=ticket,
            agent_name=otc_tickets.AGENT_NAME,
            current_year=datetime.now().year)
        msg = MIMEMultipart('related')
        msg['Subject'] = 'OTC Tracker — Ticket #{} {}'.format(
            ticket.get('id') or '', (ticket.get('status') or 'Closed').lower())
        msg['From'] = SHARED_MAILBOX
        msg['To'] = to_addr
        msg['Cc'] = _TICKET_OPS_CC
        alt = MIMEMultipart('alternative')
        alt.attach(MIMEText('Please view this notification in HTML.', 'plain', 'utf-8'))
        alt.attach(MIMEText(html, 'html', 'utf-8'))
        msg.attach(alt)
        logo_path = _get_logo_path()
        if logo_path:
            with open(logo_path, 'rb') as f:
                limg = MIMEImage(f.read())
            limg.add_header('Content-ID', '<otc_logo>')
            limg.add_header('Content-Disposition', 'inline', filename='logo.png')
            msg.attach(limg)
        _attach_email_gradient(msg)
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=20) as server:
            server.sendmail(SHARED_MAILBOX, [to_addr, _TICKET_OPS_CC], msg.as_string())
        log.info('[tickets] closing notice sent for %s to=%s cc=%s',
                 ticket.get('id'), to_addr, _TICKET_OPS_CC)
        return True
    except Exception as e:
        log.error('[tickets] closing notice FAILED for %s:\n%s',
                  ticket.get('id'), traceback.format_exc())
        return '{}: {}'.format(type(e).__name__, e)


@blueprint.route('/api/tickets', methods=['GET'])
def api_tickets_list():
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, _name, _mail = _tk_session_user()
    tickets = _tk_visible_tickets(sid)
    return jsonify({
        'success': True,
        'tickets': [_tk_public(t, sid) for t in tickets],
        'counts': otc_tickets.counts(tickets),
        'is_master': _session_is_master(),
        'agent_name': otc_tickets.AGENT_NAME,
        'statuses': otc_tickets.STATUSES,
        'priorities': otc_tickets.PRIORITIES,
        'me': {'sid': sid, 'name': session.get('user_name') or '',
               'email': session.get('user_email') or ''},
    })


@blueprint.route('/api/tickets', methods=['POST'])
def api_tickets_create():
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, name, mail = _tk_session_user()
    if not sid:
        return jsonify({'success': False, 'error': 'Session has no SID'}), 400
    data = request.get_json(silent=True) or {}
    subject = (data.get('subject') or '').strip()
    if not subject:
        return jsonify({'success': False, 'error': 'Subject is required'}), 400
    description = (data.get('description') or '').strip()
    if not description:
        return jsonify({'success': False, 'error': 'Description is required'}), 400
    tags = data.get('tags')
    if isinstance(tags, str):
        tags = [x.strip() for x in tags.split(',')]
    tags = [x.strip() for x in (tags or []) if str(x).strip()]

    # Requester, SID e status NÃO vêm do corpo: o requester é sempre quem está
    # logado (regra do usuário) e todo ticket nasce 'New'. Aceitar esses campos
    # do cliente deixaria qualquer um abrir ticket em nome de outra pessoa.
    ticket = otc_tickets.create(
        requester_sid=sid, requester_name=name, requester_email=mail,
        subject=subject, priority=(data.get('priority') or '').strip(),
        tags=tags, description=description)
    log.info('[tickets] %s created by %s (%s)', ticket['id'], name, sid)
    _tk_notify_master(sid, name, ticket)
    return jsonify({'success': True, 'ticket': _tk_public(ticket, sid)})


@blueprint.route('/api/tickets/<ticket_id>', methods=['GET'])
def api_tickets_get(ticket_id):
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, _name, _mail = _tk_session_user()
    ticket = otc_tickets.get(ticket_id)
    if not ticket:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    if not _tk_can_view(ticket, sid):
        return jsonify({'success': False, 'error': 'Not allowed'}), 403
    return jsonify({'success': True, 'ticket': _tk_public(ticket, sid),
                    'statuses': otc_tickets.STATUSES,
                    'priorities': otc_tickets.PRIORITIES,
                    'agent_name': otc_tickets.AGENT_NAME})


@blueprint.route('/api/tickets/<ticket_id>', methods=['POST'])
def api_tickets_update(ticket_id):
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, name, _mail = _tk_session_user()
    ticket = otc_tickets.get(ticket_id)
    if not ticket:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    if not _tk_can_view(ticket, sid):
        return jsonify({'success': False, 'error': 'Not allowed'}), 403

    is_master = _session_is_master()
    perms = _tk_public(ticket, sid)
    data = request.get_json(silent=True) or {}
    changes = {}
    for field in ('status', 'due_date'):
        if field in data:
            if not is_master:
                return jsonify({'success': False,
                                'error': 'Only the master can change the {}'.format(
                                    'status' if field == 'status' else 'due date')}), 403
            changes[field] = data[field]
    for field in ('subject', 'description', 'priority', 'tags'):
        if field in data:
            if not perms['can_edit_fields']:
                return jsonify({'success': False, 'error': 'Not allowed to edit this ticket'}), 403
            changes[field] = data[field]
    if not changes:
        return jsonify({'success': False, 'error': 'Nothing to update'}), 400

    was_final = (ticket.get('status') or '') in otc_tickets.FINAL_STATUSES
    updated, events = otc_tickets.update(ticket_id, changes, sid, name)
    if updated is None:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    if not events:
        return jsonify({'success': True, 'ticket': _tk_public(updated, sid), 'changed': 0})

    log.info('[tickets] %s updated by %s (%s): %s', updated['id'], name, sid,
             ', '.join(e['field'] for e in events))
    _tk_notify_requester(sid, name, updated, '#{} — {}'.format(
        updated['id'], '; '.join(e['event']['title'] for e in events)))

    # E-mail só na TRANSIÇÃO para o status terminal. Sem esse par
    # was_final/is_final, salvar de novo um ticket já encerrado (mudando a
    # prioridade, por exemplo) reenviaria o aviso ao requester.
    mail_result = None
    is_final = (updated.get('status') or '') in otc_tickets.FINAL_STATUSES
    if is_final and not was_final:
        mail_result = _tk_send_closed_email(updated)
    return jsonify({'success': True, 'ticket': _tk_public(updated, sid),
                    'changed': len(events),
                    'email_sent': mail_result is True,
                    'email_error': None if mail_result in (True, None) else mail_result})


@blueprint.route('/api/tickets/<ticket_id>/comment', methods=['POST'])
def api_tickets_comment(ticket_id):
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, name, _mail = _tk_session_user()
    ticket = otc_tickets.get(ticket_id)
    if not ticket:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    if not _tk_public(ticket, sid)['can_comment']:
        return jsonify({'success': False, 'error': 'Not allowed'}), 403
    text = ((request.get_json(silent=True) or {}).get('text') or '').strip()
    if not text:
        return jsonify({'success': False, 'error': 'Comment is empty'}), 400
    updated = otc_tickets.add_comment(ticket_id, text, sid, name)
    if updated is None:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    _tk_notify_requester(sid, name, updated,
                         '#{} — new comment'.format(updated['id']))
    return jsonify({'success': True, 'ticket': _tk_public(updated, sid)})


@blueprint.route('/api/tickets/<ticket_id>', methods=['DELETE'])
def api_tickets_delete(ticket_id):
    if not session.get('authenticated'):
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    sid, name, _mail = _tk_session_user()
    ticket = otc_tickets.get(ticket_id)
    if not ticket:
        return jsonify({'success': False, 'error': 'Ticket not found'}), 404
    if not (_session_is_master() or _tk_is_requester(ticket, sid)):
        return jsonify({'success': False,
                        'error': 'Only the requester or the master can delete a ticket'}), 403
    otc_tickets.delete(ticket_id)
    log.info('[tickets] %s deleted by %s (%s)', ticket.get('id'), name, sid)
    # O master apaga o ticket de outra pessoa: o requester precisa saber, senão
    # o item some da lista dele sem explicação.
    _tk_notify_requester(sid, name, ticket,
                         '#{} — ticket deleted'.format(ticket.get('id') or ''))
    return jsonify({'success': True})


# ==============================================================================
# NOTIFICATIONS
# ==============================================================================

@blueprint.route('/api/notifications', methods=['GET'])
def api_get_notifications():
    if not session.get('authenticated'):
        return jsonify({"success": False}), 401
    user_role = session.get('user_role', '')
    user_sid = (session.get('user_sid') or '').strip().upper()
    conn = get_db_connection()
    try:
        # target_sid endereça UM usuário e é mais forte que target_role: quando
        # está preenchido, só aquele SID vê a notificação — nem o master, nem
        # quem compartilha o papel. É o que mantém as atualizações de ticket
        # restritas ao requester.
        rows = conn.execute("""
            SELECT id, actor_sid, actor_name, action, page, detail, target_role, created_at
            FROM notifications
            WHERE DATE(created_at) = CURRENT_DATE
              AND (COALESCE(target_sid, '') = '' OR COALESCE(target_sid, '') = ?)
              AND (target_role = '' OR target_role = ?)
            ORDER BY created_at DESC
            LIMIT 50
        """, [user_sid, user_role]).fetchall()
        notifs = []
        for r in rows:
            notifs.append({
                "id": r[0],
                "actor_sid": r[1] or '',
                "actor_name": r[2] or '',
                "action": r[3] or '',
                "page": r[4] or '',
                "detail": r[5] or '',
                "created_at": r[7].isoformat() if r[7] else ''
            })
    finally:
        conn.close()

    # Page-access filter: a configured user only sees notifications for the pages
    # they can reach. Master / unconfigured users see everything. A page label with
    # no known URL, or one that isn't a controllable page, is kept.
    if not _session_is_master():
        configured, allowed = _get_page_access(session.get('user_sid', ''))
        if configured:
            def _visible(n):
                url = _NOTIF_PAGE_URL.get(n.get('page', ''))
                if not url or url not in _NAV_URLS:
                    return True
                if url == '/control-panel':
                    return _cp_page_allowed(allowed)
                return url in allowed
            notifs = [n for n in notifs if _visible(n)]
    return jsonify({"success": True, "notifications": notifs, "total_today": len(notifs)})


@blueprint.route('/api/notifications', methods=['POST'])
def api_create_notification():
    if not session.get('authenticated'):
        return jsonify({"success": False}), 401
    data        = request.get_json(silent=True) or {}
    action      = data.get('action', '').strip()
    page        = data.get('page', '').strip()
    detail      = data.get('detail', '').strip()
    target_role = data.get('target_role', '').strip()
    if not action or not page:
        return jsonify({"success": False, "message": "action and page required"}), 400
    _create_notification(
        session.get('user_sid', ''), session.get('user_name', ''),
        action, page, detail, target_role
    )
    return jsonify({"success": True})


# ── Web Push (Service Worker) ─────────────────────────────────────────────────
@blueprint.route('/sw.js')
def service_worker():
    """Serve the Service Worker at the root scope so it controls the whole app.
    The Service-Worker-Allowed header lets a /static-hosted script claim '/'."""
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                        '..', 'static', 'js', 'sw-push.js')
    try:
        with open(path, 'r', encoding='utf-8') as f:
            js = f.read()
    except Exception:
        return ('', 404)
    resp = make_response(js)
    resp.headers['Content-Type'] = 'application/javascript'
    resp.headers['Service-Worker-Allowed'] = '/'
    resp.headers['Cache-Control'] = 'no-cache'
    return resp


@blueprint.route('/api/push/public-key', methods=['GET'])
def api_push_public_key():
    from apps.pages import webpush
    return jsonify({'enabled': webpush.is_enabled(), 'key': webpush.get_public_key()})


@blueprint.route('/api/push/subscribe', methods=['POST'])
def api_push_subscribe():
    if not session.get('authenticated'):
        return jsonify({'success': False}), 401
    data = request.get_json(silent=True) or {}
    sub = data.get('subscription') or data
    endpoint = str((sub or {}).get('endpoint') or '').strip()
    if not endpoint:
        return jsonify({'success': False, 'message': 'no endpoint'}), 400
    conn = get_db_connection()
    try:
        conn.execute("DELETE FROM push_subscriptions WHERE endpoint = ?", [endpoint])
        conn.execute(
            "INSERT INTO push_subscriptions (endpoint, sid, role) VALUES (?, ?, ?)",
            [endpoint, session.get('user_sid', '') or '', session.get('user_role', '') or ''])
        conn.commit()
    finally:
        conn.close()
    return jsonify({'success': True})


@blueprint.route('/api/push/unsubscribe', methods=['POST'])
def api_push_unsubscribe():
    if not session.get('authenticated'):
        return jsonify({'success': False}), 401
    data = request.get_json(silent=True) or {}
    endpoint = str(data.get('endpoint') or '').strip()
    if endpoint:
        conn = get_db_connection()
        try:
            conn.execute("DELETE FROM push_subscriptions WHERE endpoint = ?", [endpoint])
            conn.commit()
        finally:
            conn.close()
    return jsonify({'success': True})


